css:
:root{
  --dg:#14512F; --dg2:#1B6B3E; --mg:#2E8B57; --lg:#8CC63F; --lg2:#C9E6A8;
  --cream:#FBF7EC; --cream2:#F5EFDF; --gold:#A8862F;
  --paper:#FFFFFF; --zebra:#F8FFF8; --canvas:#F6F8F5;
  --grey1:#EEF1EC; --grey2:#E3E8E0; --line:#DCE3D8; --hair:#EDF1EA;
  --tx:#1C2B22; --tx2:#33443A; --tx3:#4A5A50; --navy:#1F3555;
  --s-ok:#15633C; --s-okb:#E8F4EC; --s-warn:#8A5A12; --s-warnb:#FBF3E2;
  --s-alert:#8E2F26; --s-alertb:#FAEBE9; --s-info:#1F3555; --s-infob:#EAEFF6;
  --s-neut:#4A5A50; --s-neutb:#EFF2EE;
  --radius:8px; --shadow:0 1px 2px rgba(20,81,47,.05),0 3px 10px rgba(20,81,47,.05);
  --serif:Georgia,"Times New Roman",serif;
  --navw:246px; --navm:54px; --hdrh:54px; --fbarh:38px;
}
*{margin:0;padding:0;box-sizing:border-box}
body{background:var(--canvas);font-family:"Segoe UI",Inter,system-ui,Roboto,Arial,sans-serif;font-size:13.5px;
 color:var(--tx);line-height:1.5;-webkit-font-smoothing:antialiased}
button,input,select,textarea{font-family:inherit;font-size:13.5px;color:var(--tx)}
button{cursor:pointer;border:0;background:none}
h1,h2,h3,h4{font-family:var(--serif);font-weight:700;color:var(--dg)}
::-webkit-scrollbar{width:9px;height:9px}
::-webkit-scrollbar-track{background:var(--grey1)}
::-webkit-scrollbar-thumb{background:#BFCCB8;border-radius:6px}
::-webkit-scrollbar-thumb:hover{background:var(--mg)}
:focus-visible{outline:2px solid var(--mg);outline-offset:1px}

/* ===== HEADER (minimum height, logo left / home / title / user right) ===== */
.top{position:fixed;left:0;right:0;top:0;height:var(--hdrh);z-index:90;display:flex;align-items:center;
 justify-content:space-between;gap:12px;padding:0 12px 0 10px;background:linear-gradient(100deg,var(--dg),var(--dg2) 58%,var(--mg));
 border-bottom:2px solid var(--lg);box-shadow:0 1px 6px rgba(20,81,47,.16)}
.tleft{display:flex;align-items:center;gap:9px;flex-shrink:0;min-width:0}
.tlogo{height:34px;width:96px;background:#fff;border-radius:5px;padding:3px 5px;display:flex;align-items:center;
 justify-content:center;flex-shrink:0;box-shadow:0 1px 3px rgba(0,0,0,.16)}
.tlogo svg{width:100%;height:100%}
.hombtn{display:inline-flex;align-items:center;gap:5px;height:28px;padding:0 10px;border-radius:6px;
 background:rgba(255,255,255,.13);border:1px solid rgba(255,255,255,.22);color:#fff;font-size:11.5px;font-weight:600;
 letter-spacing:.4px;transition:background .16s,color .16s}
.hombtn:hover{background:var(--lg);color:var(--dg);border-color:var(--lg)}
.hombtn span{display:inline-block}
.tmid{flex:1;min-width:0;text-align:center;line-height:1.05}
.top h1{font-family:var(--serif);font-size:17px;font-weight:700;letter-spacing:2.4px;color:#fff;text-transform:uppercase;
 white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.top .tsub{display:block;font-size:8.5px;letter-spacing:2.4px;text-transform:uppercase;color:var(--lg2);font-weight:600;margin-top:1px}
.tright{display:flex;align-items:center;gap:8px;height:34px;padding:0 9px 0 6px;border-radius:7px;cursor:pointer;flex-shrink:0;
 background:rgba(255,255,255,.11);border:1px solid rgba(255,255,255,.2);transition:background .16s}
.tright:hover{background:rgba(255,255,255,.2)}
.uav{width:24px;height:24px;border-radius:50%;background:var(--lg);color:var(--dg);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.uinfo{display:flex;flex-direction:column;line-height:1.15;min-width:0}
.uinfo b{font-size:11.5px;font-weight:700;color:#fff;white-space:nowrap;max-width:150px;overflow:hidden;text-overflow:ellipsis}
.uinfo span{font-size:8.5px;letter-spacing:1px;text-transform:uppercase;color:var(--lg2);white-space:nowrap;max-width:150px;overflow:hidden;text-overflow:ellipsis}
.uarr{font-size:9px;color:var(--lg2)}
.navbtn{display:none;width:30px;height:30px;border-radius:6px;background:rgba(255,255,255,.13);color:#fff;font-size:15px;
 align-items:center;justify-content:center;flex-shrink:0}
.navbtn:hover{background:var(--lg);color:var(--dg)}

/* ===== FIXED FILTER BAR (never under the menu) ===== */
.fdock{position:fixed;top:var(--hdrh);left:var(--navw);right:0;z-index:75;background:var(--paper);
 border-bottom:1px solid var(--line);transition:left .22s cubic-bezier(.4,0,.2,1);box-shadow:0 1px 4px rgba(20,81,47,.05)}
body.mini .fdock{left:var(--navm)}
.fhandle{display:flex;align-items:center;gap:10px;height:var(--fbarh);padding:0 16px;background:var(--cream);
 border-bottom:1px solid var(--line);cursor:pointer}
.fhandle .fh-t{font-size:10.5px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase;color:var(--dg);flex-shrink:0}
.fhandle .fh-c{display:flex;gap:5px;flex-wrap:nowrap;overflow:hidden;flex:1}
.fhandle .fh-a{color:var(--mg);font-size:11px;flex-shrink:0;transition:transform .22s;line-height:1}
.fdock.open .fhandle .fh-a{transform:rotate(180deg)}
.fbody{max-height:0;overflow:hidden;transition:max-height .26s cubic-bezier(.4,0,.2,1)}
.fdock.open .fbody{max-height:460px}
.fpad{padding:12px 16px 11px}
.frow1{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:9px 11px;align-items:end}
.frow2{display:flex;gap:7px;flex-wrap:wrap;align-items:center;margin-top:11px;padding-top:10px;border-top:1px solid var(--hair)}
.fg{display:flex;flex-direction:column;gap:3px;min-width:0}
.fg label{font-size:10px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;color:var(--tx3)}
.fg select,.fg input,.fg textarea{width:100%;border:1px solid var(--line);border-radius:6px;padding:6px 9px;
 background:var(--paper);min-height:32px;font-size:12.5px;color:var(--tx)}
.fg select{appearance:none;background-image:linear-gradient(45deg,transparent 50%,var(--mg) 50%),linear-gradient(135deg,var(--mg) 50%,transparent 50%);
 background-position:calc(100% - 14px) 14px,calc(100% - 9px) 14px;background-size:5px 5px;background-repeat:no-repeat;padding-right:26px}
.fg select:hover,.fg input:hover{border-color:var(--mg)}
.fg select:focus,.fg input:focus{border-color:var(--mg);outline:none;box-shadow:0 0 0 2px rgba(46,139,87,.12)}
.rngwrap{display:flex;gap:5px;align-items:center}
.rngwrap input{text-align:right}
.rngwrap span{font-size:10.5px;color:var(--tx3);flex-shrink:0}
.btn{border-radius:6px;padding:0 12px;font-size:12.5px;font-weight:600;border:1px solid var(--line);background:var(--paper);
 color:var(--tx2);white-space:nowrap;height:30px;display:inline-flex;align-items:center;gap:5px}
.btn:hover{border-color:var(--mg);color:var(--dg);background:var(--zebra)}
.btn.pri{background:var(--dg2);color:#fff;border-color:var(--dg2)}
.btn.pri:hover{background:var(--dg);color:#fff}
.btn.au{background:var(--cream2);color:var(--gold);border-color:#E4D9BC}
.btn.au:hover{background:#EFE6CC;color:var(--gold)}
.btn.sm{height:26px;padding:0 10px;font-size:11.5px}
.btn:disabled{opacity:.45;cursor:not-allowed}
.chip{display:inline-flex;align-items:center;height:20px;border-radius:4px;padding:0 8px;font-size:10.5px;font-weight:600;
 background:var(--grey1);border:1px solid var(--line);color:var(--tx2);white-space:nowrap}
.chip.g{background:var(--cream);border-color:#E4D9BC;color:var(--gold)}
.chip.f,.chip.mid,.chip.leaf,.chip.p,.chip.c4{background:var(--zebra);border-color:var(--lg2);color:var(--dg)}
.chip.b,.chip.c3{background:var(--s-infob);border-color:#CBD6E5;color:var(--navy)}
.chip.a,.chip.c2{background:var(--s-alertb);border-color:#E8CCC8;color:var(--s-alert)}
.chip.w,.chip.c1{background:var(--s-warnb);border-color:#E7D9B4;color:var(--s-warn)}
.chip.c5{background:var(--s-okb);border-color:#C4E0CE;color:var(--s-ok)}
.chip.solid{background:var(--dg);color:#fff;border-color:var(--dg)}

/* ===== SIDE MENU — modern dot & line navigator ===== */
.side{position:fixed;left:0;top:var(--hdrh);bottom:0;width:var(--navw);z-index:80;display:flex;flex-direction:column;
 background:linear-gradient(180deg,#0F3F25,#14512F 42%,#173F28);transition:width .24s cubic-bezier(.4,0,.2,1),transform .24s;
 overflow:hidden;box-shadow:2px 0 10px rgba(0,0,0,.1)}
body.mini .side{width:var(--navm)}
.sbhd{display:flex;align-items:center;gap:8px;height:var(--fbarh);padding:0 10px;
 border-bottom:1px solid rgba(255,255,255,.12);flex-shrink:0}
.sbhd .st{flex:1;font-size:9.5px;font-weight:700;letter-spacing:1.9px;text-transform:uppercase;color:var(--lg2);white-space:nowrap;overflow:hidden}
.sbtog{width:26px;height:26px;border-radius:6px;background:rgba(255,255,255,.11);color:#fff;font-size:11px;
 display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:background .16s}
.sbtog:hover{background:var(--lg);color:var(--dg)}
.sbtog i{font-style:normal;display:block;transition:transform .24s}
body.mini .sbtog i{transform:rotate(180deg)}
.sbsrch{padding:8px;flex-shrink:0}
.sbsrch input{width:100%;border:1px solid rgba(255,255,255,.18);border-radius:7px;padding:7px 10px;font-size:12.5px;
 background:rgba(255,255,255,.08);color:#fff}
.sbsrch input::placeholder{color:rgba(255,255,255,.48)}
.sbsrch input:focus{border-color:var(--lg);outline:none;background:rgba(255,255,255,.15)}
body.mini .sbsrch,body.mini .sbhd .st{display:none}
.menuwrap{flex:1;overflow-y:auto;overflow-x:hidden;padding:4px 0 22px}
.menuwrap::-webkit-scrollbar{width:5px}
.menuwrap::-webkit-scrollbar-track{background:transparent}
.menuwrap::-webkit-scrollbar-thumb{background:rgba(255,255,255,.22);border-radius:4px}

/* --- main menu row --- */
.mgrp{margin:2px 7px;border-radius:9px;overflow:hidden;transition:background .2s}
.mgrp.open{background:rgba(255,255,255,.055)}
.mgrp.has{box-shadow:inset 0 0 0 1px rgba(140,198,63,.34)}
.mgh{width:100%;display:flex;align-items:center;gap:10px;padding:9px 10px;text-align:left;font-size:11.5px;
 font-weight:700;letter-spacing:.8px;color:#E8F3E2;background:transparent;transition:background .16s,color .16s;position:relative}
.mgh:hover{background:rgba(255,255,255,.09);color:#fff}
.mgrp.open .mgh{color:#fff}
.mgrp.has .mgh{color:#fff}
.mgh .gi{width:26px;height:26px;border-radius:7px;flex-shrink:0;display:flex;align-items:center;justify-content:center;
 font-size:13px;color:var(--lg);background:rgba(140,198,63,.14);border:1px solid rgba(140,198,63,.24);transition:all .18s}
.mgrp.open .mgh .gi,.mgrp.has .mgh .gi{background:var(--lg);color:var(--dg);border-color:var(--lg)}
.mgh .gt{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mgh .gc{font-size:9px;font-weight:700;color:var(--lg2);background:rgba(255,255,255,.1);border-radius:20px;padding:1px 6px;flex-shrink:0}
.mgh .ga{font-size:8px;color:var(--lg2);transition:transform .26s;flex-shrink:0;margin-left:2px}
.mgrp.open .mgh .ga{transform:rotate(90deg);color:var(--lg)}

/* --- dot & line sub menu --- */
.mitems{max-height:0;overflow:hidden;transition:max-height .3s cubic-bezier(.4,0,.2,1);position:relative}
.mgrp.open .mitems{max-height:820px}
.mitems .rail{position:absolute;left:22px;top:4px;bottom:8px;width:1.5px;
 background:linear-gradient(180deg,rgba(140,198,63,.7),rgba(140,198,63,.16));border-radius:2px}
.mrow{width:100%;display:flex;align-items:center;gap:10px;padding:7px 9px 7px 12px;text-align:left;font-size:12px;
 color:#CFE3C6;background:transparent;position:relative;transition:color .16s,background .16s;border-radius:7px}
.mrow .dot{width:20px;height:20px;flex-shrink:0;display:flex;align-items:center;justify-content:center;position:relative;z-index:2}
.mrow .dot::before{content:"";width:7px;height:7px;border-radius:50%;background:#14512F;
 box-shadow:0 0 0 2px rgba(140,198,63,.55);transition:all .18s}
.mrow:hover{background:rgba(255,255,255,.075);color:#fff}
.mrow:hover .dot::before{background:var(--lg2);box-shadow:0 0 0 2.5px rgba(140,198,63,.8)}
.mrow .mt{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.25}
.mrow .mt em{display:block;font-style:normal;font-size:9px;letter-spacing:.3px;color:rgba(255,255,255,.42);
 white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:1px}
.mrow .ms{font-size:11px;color:rgba(255,255,255,.34);flex-shrink:0;padding:0 2px}
.mrow .ms.fav,.mrow .ms:hover{color:var(--gold2,#E5C76B)}
/* selected */
.mrow.on{background:linear-gradient(90deg,rgba(140,198,63,.28),rgba(140,198,63,.06));color:#fff;font-weight:700}
.mrow.on::after{content:"";position:absolute;right:0;top:6px;bottom:6px;width:3px;border-radius:3px 0 0 3px;background:var(--lg)}
.mrow.on .dot::before{width:9px;height:9px;background:var(--lg);box-shadow:0 0 0 3px rgba(140,198,63,.35),0 0 9px rgba(140,198,63,.85)}
.mrow.on .mt em{color:rgba(255,255,255,.6)}

/* mini (icon) mode */
body.mini .mgrp{margin:2px 5px}
body.mini .mgh{justify-content:center;padding:9px 4px}
body.mini .mgh .gt,body.mini .mgh .ga,body.mini .mgh .gc{display:none}
body.mini .mitems .rail{display:none}
body.mini .mrow{justify-content:center;padding:7px 2px}
body.mini .mrow .mt,body.mini .mrow .ms{display:none}
body.mini .mrow .dot{width:26px}
body.mini .mgh,body.mini .mrow{position:relative}
body.mini .mgh:hover::after,body.mini .mrow:hover::after{content:attr(data-tip);position:absolute;left:calc(100% + 8px);top:50%;
 transform:translateY(-50%);background:var(--dg);color:#fff;font-size:11px;font-weight:600;padding:5px 9px;border-radius:6px;
 white-space:nowrap;z-index:200;box-shadow:0 3px 10px rgba(0,0,0,.3);border:1px solid var(--lg)}
body.mini .mrow.on::after{display:none}
.mnone{padding:14px;font-size:11.5px;color:rgba(255,255,255,.55);line-height:1.5}

/* ===== MAIN ===== */
.main{margin-left:var(--navw);padding:calc(var(--hdrh) + var(--fbarh) + 14px) 16px 44px;transition:margin-left .22s}
body.mini .main{margin-left:var(--navm)}
.ptitle{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:9px 14px;margin-bottom:12px;border-radius:var(--radius);
 background:var(--paper);border:1px solid var(--line);border-left:4px solid var(--mg)}
.ptitle h2{font-size:17px;line-height:1.2}
.ptitle .psub{font-size:11.5px;color:var(--tx3);margin-top:1px;line-height:1.35}
.ptitle .pm{margin-left:auto;display:flex;gap:6px;flex-wrap:wrap;align-items:center}

/* ===== SECTION — small green arrow, low header ===== */
.sec{background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);margin-bottom:12px;overflow:hidden;
 box-shadow:var(--shadow)}
.sec>.sh{width:100%;display:flex;align-items:center;gap:9px;padding:8px 13px;text-align:left;background:var(--paper);
 border-bottom:1px solid var(--hair);min-height:38px}
.sec>.sh:hover{background:var(--zebra)}
.sec>.sh .sar{color:var(--mg);font-size:11px;flex-shrink:0;transition:transform .24s;line-height:1;width:12px}
.sec.cl>.sh .sar{transform:rotate(-90deg)}
.sec>.sh .sn{font-size:10.5px;font-weight:700;color:var(--mg);flex-shrink:0;letter-spacing:.6px}
.sec>.sh .stx{min-width:0;flex:1}
.sec>.sh h3{font-size:14px;line-height:1.25;display:inline}
.sec>.sh .snote{display:block;font-size:11px;color:var(--tx3);margin-top:1px;font-weight:400;line-height:1.3}
.sec>.sh .meta{display:flex;gap:5px;flex-wrap:wrap;justify-content:flex-end;align-items:center}
.sec>.sbwrap{display:grid;grid-template-rows:1fr;transition:grid-template-rows .26s cubic-bezier(.4,0,.2,1)}
.sec.cl>.sbwrap{grid-template-rows:0fr}
.sec>.sbwrap>.sb{overflow:hidden;padding:12px 13px}
.sec>.sbwrap>.sb.flush{padding:0}
.sec.cl>.sbwrap>.sb{padding-top:0;padding-bottom:0}
.winbtn{border-radius:4px;padding:2px 8px;font-size:10.5px;font-weight:600;background:var(--paper);border:1px solid var(--line);color:var(--tx3)}
.winbtn:hover{border-color:var(--mg);color:var(--dg)}
.subhead{font-size:13px;font-family:var(--serif);font-weight:700;color:var(--dg);margin:14px 0 8px;padding-bottom:5px;
 border-bottom:1px solid var(--hair)}
.subhead:first-child{margin-top:0}

/* ===== TABLES ===== */
.tw{overflow-x:auto;width:100%;border-top:1px solid var(--hair)}
table.dt{width:100%;min-width:100%;border-collapse:separate;border-spacing:0;font-size:12.5px;background:var(--paper)}
.dt th{position:sticky;top:0;z-index:3;text-align:left;padding:8px 10px;font-size:10.5px;font-weight:700;letter-spacing:.5px;
 text-transform:uppercase;color:var(--dg);background:var(--cream);border-bottom:2px solid var(--mg);
 border-right:1px solid rgba(20,81,47,.07);white-space:nowrap;cursor:pointer;user-select:none}
.dt th:hover{background:var(--cream2)}
.dt th.asc:after{content:" \25B4";color:var(--mg)}
.dt th.desc:after{content:" \25BE";color:var(--mg)}
.dt th.r,.dt td.r{text-align:right}
.dt td{padding:7px 10px;border-bottom:1px solid var(--hair);color:var(--tx);vertical-align:middle}
.dt tbody tr{background:var(--paper)}
.dt tbody tr:nth-child(even){background:var(--zebra)}
.dt tbody tr:hover{background:#F1F7F1}
.dt tbody tr.clk{cursor:pointer}
.dt td b{font-weight:600;color:var(--tx)}
.dt td .sub{display:block;font-size:11px;color:var(--tx3);font-weight:400;margin-top:1px;line-height:1.3}
.dt td .sub.a1{color:var(--s-warn)}.dt td .sub.a2{color:var(--s-alert)}.dt td .sub.a3{color:var(--navy)}
.dt td .sub.a5{color:var(--s-ok)}.dt td .sub.g{color:var(--tx3)}
.dt tr.grp td{background:var(--cream)!important;font-family:var(--serif);font-size:13px;font-weight:700;color:var(--dg);
 border-top:1px solid var(--mg)}
.dt tr.grp2 td{background:var(--grey1)!important;font-weight:600;color:var(--tx2)}
.dt tfoot td{background:var(--cream2)!important;font-weight:700;color:var(--dg);border-top:2px solid var(--mg);padding:8px 10px}
.dt tr.note td{background:var(--s-infob)!important;color:var(--navy);font-weight:600;font-size:11px}
.num{font-variant-numeric:tabular-nums}
.pill{display:inline-flex;align-items:center;justify-content:center;height:21px;min-width:66px;padding:0 9px;
 border-radius:4px;font-size:10.5px;font-weight:700;letter-spacing:.3px;border:1px solid transparent;white-space:nowrap}
.p-ok,.p-t{background:var(--s-okb);color:var(--s-ok);border-color:#C4E0CE}
.p-lf{background:var(--zebra);color:var(--dg);border-color:var(--lg2)}
.p-w{background:var(--s-warnb);color:var(--s-warn);border-color:#E7D9B4}
.p-b{background:var(--s-alertb);color:var(--s-alert);border-color:#E8CCC8}
.p-i{background:var(--s-infob);color:var(--navy);border-color:#CBD6E5}
.p-v{background:var(--cream);color:var(--gold);border-color:#E4D9BC}
.p-n{background:var(--s-neutb);color:var(--s-neut);border-color:var(--line)}
.pag{display:flex;align-items:center;justify-content:flex-end;gap:5px;padding:8px 12px;background:var(--cream);
 border-top:1px solid var(--line);flex-wrap:wrap}
.pag .pinfo{margin-right:auto;font-size:11.5px;color:var(--tx3);font-weight:600}
.pag button{min-width:28px;height:26px;padding:0 8px;border-radius:5px;border:1px solid var(--line);background:var(--paper);
 font-size:12px;font-weight:600;color:var(--tx2)}
.pag button:hover:not(:disabled){border-color:var(--mg);color:var(--dg)}
.pag button.on{background:var(--dg2);color:#fff;border-color:var(--dg2)}
.pag button:disabled{opacity:.4;cursor:not-allowed}
.pag .pdots{color:var(--tx3);padding:0 2px}

/* ===== KPI ===== */
.kgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(176px,1fr));gap:10px}
.kpi{position:relative;background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);padding:11px 13px;
 border-left:3px solid var(--mg);box-shadow:var(--shadow)}
.kpi:nth-child(even){border-left-color:var(--gold)}
