.kpi.k1{border-left-color:var(--s-warn)!important}.kpi.k1 b{color:var(--s-warn)}
.kpi.k2{border-left-color:var(--s-alert)!important}.kpi.k2 b{color:var(--s-alert)}
.kpi.k3{border-left-color:var(--navy)!important}.kpi.k3 b{color:var(--navy)}
.kpi.k4{border-left-color:var(--gold)!important}.kpi.k4 b{color:var(--gold)}
.kpi.k5{border-left-color:var(--s-ok)!important}.kpi.k5 b{color:var(--s-ok)}
.kpi.kl{border-left-color:var(--gold)!important}.kpi.kl b{color:var(--gold)}
.hero{background:var(--paper);border:1px solid var(--line);border-left:4px solid var(--dg2);border-radius:var(--radius);
 padding:14px 18px;display:flex;align-items:center;gap:22px;flex-wrap:wrap;margin-bottom:12px;box-shadow:var(--shadow)}
