.cbar .cb{flex:1;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:3px;height:100%}
.cbar .cb u{display:block;width:100%;border-radius:2px 2px 0 0;text-decoration:none;background:var(--mg)}
.cbar .cb u.a1{background:var(--gold)}
.cbar .cb u.a3{background:var(--dg2)}
.cbar .cb s{text-decoration:none;font-size:10.5px;font-weight:700;color:var(--tx2)}
