.cxl span{flex:1;text-align:center;font-size:10.5px;font-weight:600;color:var(--tx3)}
.note-s{font-size:11.5px;color:var(--tx3);padding:7px 2px 2px;line-height:1.5}
.chartbox{padding:3px 2px}

/* ===== PROFILE / DRAWER ===== */
.pgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:1px;background:var(--hair);
 border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}
