.pgrid div:nth-child(even){background:var(--zebra)}
.pgrid label{display:block;font-size:9.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;color:var(--tx3)}
.pgrid b{font-size:12.5px;font-weight:600;color:var(--tx)}
.phead{display:flex;gap:14px;align-items:center;flex-wrap:wrap;padding:13px 16px;border-radius:var(--radius) var(--radius) 0 0;
 color:#fff;background:linear-gradient(100deg,var(--dg),var(--dg2));border-bottom:3px solid var(--lg)}
