.phead .hs span{font-size:9.5px;color:var(--lg2);text-transform:uppercase;letter-spacing:.9px;font-weight:700}
.ph{width:52px;height:64px;border-radius:5px;display:flex;align-items:center;justify-content:center;text-align:center;
 line-height:1.3;font-size:10px;font-weight:600;color:var(--tx3);background:var(--grey1);border:1px solid var(--line)}
.phw{display:flex;gap:5px;flex-wrap:wrap}
.xbtn{width:20px;height:20px;border-radius:4px;background:transparent;border:1px solid var(--line);color:var(--mg);
 font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center}
.xbtn:hover{background:var(--zebra);border-color:var(--mg)}
.dt tr.xrow td{background:var(--zebra)!important;padding:0;border-bottom:2px solid var(--mg)}
.drawer{padding:12px 14px;display:grid;gap:10px}
.dsec{background:var(--paper);border:1px solid var(--line);border-radius:6px;overflow:hidden}
.dsec .dh{font-size:11px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;color:var(--dg);padding:7px 11px;
 background:var(--cream);border-bottom:1px solid var(--line)}
.dgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(178px,1fr));gap:1px;background:var(--hair)}
.dgrid div{background:var(--paper);padding:7px 11px}
.dgrid div:nth-child(even){background:var(--zebra)}
.dgrid label{display:block;font-size:9.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;color:var(--tx3)}
.dgrid b{font-size:12px;font-weight:600;color:var(--tx)}
.drow{display:flex;gap:7px;flex-wrap:wrap;padding:2px 0}
