.cat-derm{background:var(--s-okb);color:var(--s-ok);border-color:#C4E0CE}
.cat-hair{background:var(--cream);color:var(--gold);border-color:#E4D9BC}
.cat-ht{background:var(--s-warnb);color:var(--s-warn);border-color:#E7D9B4}
.cat-aes{background:var(--s-alertb);color:var(--s-alert);border-color:#E8CCC8}
.cat-rise{background:var(--s-infob);color:var(--navy);border-color:#CBD6E5}
.tick{font-size:12px;font-weight:700}.tick.yes{color:var(--s-ok)}.tick.no{color:var(--s-alert)}
.prefc{display:inline-flex;align-items:center;height:19px;gap:4px;border-radius:4px;padding:0 8px;font-size:10px;
 font-weight:600;background:var(--grey1);color:var(--tx2);border:1px solid var(--line)}
.cardstrip{display:grid;grid-template-columns:repeat(auto-fit,minmax(176px,1fr));gap:10px;margin-bottom:12px}
.cardtile{position:relative;background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);padding:11px 13px;
 cursor:pointer;border-top:3px solid var(--mg);box-shadow:var(--shadow)}
