.cardtile label{display:block;font-size:9.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;color:var(--tx3)}
.cardtile b{display:block;font-family:var(--serif);font-size:21px;font-weight:700;margin-top:2px;color:var(--dg)}
.cardtile em{display:block;font-style:normal;font-size:10px;color:var(--tx3);margin-top:2px}
.cardtile .cn2{display:block;font-size:10px;color:var(--tx3);margin-top:6px;padding-top:6px;border-top:1px solid var(--hair);line-height:1.35}
.cardtile.t-ok{border-top-color:var(--s-ok)}.cardtile.t-ok b{color:var(--s-ok)}
.cardtile.t-i{border-top-color:var(--navy)}.cardtile.t-i b{color:var(--navy)}
.cardtile.t-w{border-top-color:var(--s-warn)}.cardtile.t-w b{color:var(--s-warn)}
.cardtile.t-b{border-top-color:var(--s-alert)}.cardtile.t-b b{color:var(--s-alert)}
.cardtile.t-n{border-top-color:var(--gold)}.cardtile.t-n b{color:var(--gold)}
.segwrap{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:9px}
.segchip{display:inline-flex;align-items:center;height:28px;gap:6px;border-radius:5px;padding:0 11px;font-size:12px;
 font-weight:600;background:var(--paper);border:1px solid var(--line);color:var(--tx2)}
.segchip:hover{border-color:var(--mg);background:var(--zebra)}
.segchip b{font-size:11.5px;background:var(--grey1);border-radius:3px;padding:1px 6px;color:var(--dg)}
.segchip.w b{background:var(--s-warnb);color:var(--s-warn)}
.segchip.b b{background:var(--s-alertb);color:var(--s-alert)}
.segchip.i b{background:var(--s-infob);color:var(--navy)}
.segchip.v b{background:var(--cream);color:var(--gold)}
.msgprev{background:var(--paper);border:1px solid var(--line);border-radius:6px;overflow:hidden}
.msgprev .mp-hd{padding:8px 12px;background:var(--dg);color:#fff;font-size:11px;font-weight:700;border-bottom:2px solid var(--lg)}
.msgprev .mp-sub{padding:8px 12px;font-family:var(--serif);font-size:13px;font-weight:700;color:var(--dg);
 background:var(--cream);border-bottom:1px solid var(--hair)}
.msgprev .mp-body{padding:12px 14px;font-size:12.5px;line-height:1.65;min-height:100px;color:var(--tx)}
.msgprev .mp-ft{padding:7px 12px;background:var(--zebra);border-top:1px solid var(--hair);font-size:10px;color:var(--tx3)}
input.msel{width:15px;height:15px;accent-color:var(--dg2);cursor:pointer}
.tplgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(196px,1fr));gap:8px;margin-bottom:10px}
.tplcard{border:1px solid var(--line);border-radius:6px;padding:9px 11px;background:var(--paper);cursor:pointer;border-left:3px solid var(--line)}
.tplcard:hover{border-color:var(--mg);border-left-color:var(--mg)}
.tplcard.on{background:var(--zebra);border-color:var(--mg);border-left-color:var(--dg2)}
.tplcard b{display:block;font-size:12px;font-weight:700;color:var(--dg)}
.tplcard span{display:block;font-size:10.5px;color:var(--tx3);margin-top:2px;line-height:1.35}
.srchbox{display:flex;gap:8px;margin-bottom:9px}
.srchbox input{flex:1;border:1px solid var(--line);border-radius:6px;padding:10px 13px;font-size:14px;background:var(--paper)}
.srchbox input:focus{border-color:var(--mg);outline:none;box-shadow:0 0 0 2px rgba(46,139,87,.12)}
.hits{border:1px solid var(--line);border-radius:6px;overflow:hidden;background:var(--paper)}
.hit{display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid var(--hair);cursor:pointer}
.hit:nth-child(even){background:var(--zebra)}
.hit:hover{background:#F1F7F1}
.hit .hn{flex:1;min-width:0}
.hit .hn b{display:block;font-size:12.5px;font-weight:600;color:var(--tx)}
.hit .hn span{display:block;font-size:10.5px;color:var(--tx3)}
.hit .hv{font-weight:700;color:var(--dg);white-space:nowrap}
.note{border-radius:6px;padding:10px 13px;font-size:12.5px;color:var(--tx2);background:var(--zebra);border:1px solid var(--lg2)}
.note.g{background:var(--cream);border-color:#E4D9BC;color:var(--gold)}
.empty{border-radius:var(--radius);padding:38px 20px;text-align:center;color:var(--tx3);background:var(--paper);border:1px solid var(--line)}
.empty b{display:block;font-family:var(--serif);font-size:16px;color:var(--dg);margin-bottom:6px}
.toast{position:fixed;top:calc(var(--hdrh) + 12px);right:18px;transform:translateX(130%);padding:10px 15px;border-radius:6px;
 background:var(--paper);border:1px solid var(--line);border-left:3px solid var(--mg);font-weight:600;z-index:400;
 box-shadow:0 4px 16px rgba(20,81,47,.12);transition:transform .26s;color:var(--tx)}
.toast.on{transform:translateX(0)}
.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.legend{display:flex;gap:12px;flex-wrap:wrap;padding:8px 12px;border-radius:6px;background:var(--paper);border:1px solid var(--line);
 font-size:10.5px;font-weight:600;color:var(--tx3);margin-bottom:12px}
.legend span{display:inline-flex;align-items:center;gap:5px}
.legend i{width:9px;height:9px;border-radius:2px;display:inline-block}
.ovl{position:fixed;inset:0;background:rgba(20,81,47,.42);display:none;align-items:flex-start;justify-content:center;
 padding:20px 12px;z-index:300;overflow-y:auto}
.ovl.on{display:flex}
.modal{width:100%;max-width:1420px;border-radius:var(--radius);overflow:hidden;background:var(--canvas);border:1px solid var(--line)}
.modal.narrow{max-width:880px}
.m-hd{display:flex;align-items:center;gap:10px;padding:11px 15px;color:#fff;background:var(--dg);border-bottom:3px solid var(--lg)}
.m-hd h4{font-size:15px;flex:1;color:#fff}
.m-x{width:26px;height:26px;border-radius:5px;background:rgba(255,255,255,.12);color:#fff;font-size:12px;font-weight:700}
.m-x:hover{background:var(--lg);color:var(--dg)}
.m-w{border-radius:5px;padding:4px 10px;background:rgba(255,255,255,.12);color:#fff;font-size:11px;font-weight:600}
.m-w:hover{background:var(--lg);color:var(--dg)}
.m-bd{padding:14px 16px;max-height:80vh;overflow-y:auto}
.cpwrap{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px}
.cpcard{border:1px solid var(--line);border-radius:6px;padding:12px 14px;background:var(--paper);border-top:2px solid var(--mg)}
.cpcard:nth-child(even){border-top-color:var(--gold)}
.cpcard h5{font-size:13px;font-family:var(--serif);color:var(--dg);margin-bottom:9px;padding-bottom:6px;border-bottom:1px solid var(--hair)}
.cptable{width:100%;border-collapse:collapse;font-size:12.5px}
.cptable th{background:var(--cream);color:var(--dg);text-align:left;padding:7px 10px;font-size:10px;letter-spacing:.8px;
 text-transform:uppercase;font-weight:700;border-bottom:2px solid var(--mg)}
.cptable td{padding:6px 10px;border-bottom:1px solid var(--hair);color:var(--tx)}
.cptable tr:nth-child(even) td{background:var(--zebra)}
.cptable select{border:1px solid var(--line);border-radius:5px;padding:4px 7px;font-size:12px;background:var(--paper)}
.cptable input[type=checkbox]{width:15px;height:15px;accent-color:var(--dg2)}
.togrow{display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--hair)}
.togrow:last-child{border-bottom:0}
.togrow .tl{flex:1}
.togrow .tl b{display:block;font-size:12.5px;font-weight:600;color:var(--tx)}
.togrow .tl span{display:block;font-size:10.5px;color:var(--tx3)}
.swg{position:relative;display:inline-block;width:36px;height:20px;flex-shrink:0}
.swg input{opacity:0;width:0;height:0}
.swg .sl2{position:absolute;inset:0;background:var(--grey2);border-radius:99px;transition:.2s}
.swg .sl2:before{content:"";position:absolute;height:14px;width:14px;left:3px;top:3px;background:#fff;border-radius:50%;transition:.2s}
.swg input:checked+.sl2{background:var(--mg)}
.swg input:checked+.sl2:before{transform:translateX(16px)}
.lvltabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:11px}
.lvltab{height:30px;border-radius:5px;padding:0 13px;font-size:12.5px;font-weight:600;background:var(--paper);
 border:1px solid var(--line);color:var(--tx2);display:inline-flex;align-items:center}
.lvltab:hover{border-color:var(--mg);background:var(--zebra)}
.lvltab.on{background:var(--dg2);color:#fff;border-color:var(--dg2)}

/* ===== RESPONSIVE ===== */
@media(max-width:1200px){.two,.cpwrap{grid-template-columns:1fr}}
