 .navbtn{display:flex}
 .top h1{font-size:14px;letter-spacing:1.2px}
 .top .tsub{display:none}
 .hombtn span{display:none}.hombtn{padding:0 8px}
 .uinfo{display:none}.tright{padding:0 6px}
 .tlogo{width:74px;height:30px}
