 .frow1{grid-template-columns:repeat(auto-fit,minmax(140px,1fr))}}
@media(max-width:560px){
 .kgrid,.cardstrip{grid-template-columns:1fr 1fr}
 .ptitle{padding:8px 11px}.ptitle h2{font-size:15px}
