 .pag .pinfo{width:100%;margin-bottom:5px}}
@media(min-width:861px){.scrim{display:none!important}}
@media print{.top,.fdock,.side,.toast,.m-x,.m-w,.winbtn,.btn,.pag,.navbtn,.scrim{display:none!important}
 .main{margin-left:0;padding:0}.sec{break-inside:avoid;box-shadow:none}
 .sec.cl>.sbwrap{grid-template-rows:1fr!important}.sec.cl>.sbwrap>.sb{padding:12px 13px!important}}

/* ===== BRANCH ACCOUNTS — cash book, T-format, movement strip ===== */
:root{--cr:#A33227; --crb:#FCF0EE; --crl:#EBD3CF; --drk:#15633C; --drb:#EDF7F0; --drl:#CBE4D5}
.batabs{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:0 0 10px}
.batab{height:30px;padding:0 13px;border-radius:20px;border:1px solid var(--line);background:var(--paper);
 font-size:12px;font-weight:600;color:var(--tx2);display:inline-flex;align-items:center;gap:6px;transition:all .16s}
.batab:hover{border-color:var(--mg);color:var(--dg);background:var(--zebra)}
.batab.on{background:var(--dg2);border-color:var(--dg2);color:#fff;box-shadow:0 2px 6px rgba(20,81,47,.2)}
.batab .n{font-size:10px;opacity:.85;font-weight:700}
.bascroll{display:flex;gap:6px;overflow-x:auto;padding:2px 0 8px}
.bascroll::-webkit-scrollbar{height:6px}
.daychip{flex-shrink:0;min-width:104px;border:1px solid var(--line);border-radius:9px;background:var(--paper);
 padding:6px 10px;text-align:left;transition:all .16s}
.daychip b{display:block;font-size:11.5px;font-weight:700;color:var(--tx);white-space:nowrap}
.daychip span{display:block;font-size:10px;color:var(--tx3);margin-top:1px;white-space:nowrap}
.daychip em{display:block;font-style:normal;font-size:11px;font-weight:700;margin-top:3px;color:var(--drk)}
.daychip:hover{border-color:var(--mg);background:var(--zebra)}
.daychip.on{border-color:var(--dg2);background:var(--drb);box-shadow:inset 0 0 0 1px var(--dg2)}
.daychip.neg em{color:var(--cr)}

/* cash movement strip */
.cflow{display:grid;grid-template-columns:repeat(auto-fit,minmax(148px,1fr));gap:8px;margin:2px 0 12px}
.cfi{border:1px solid var(--line);border-radius:9px;background:var(--paper);padding:9px 11px;position:relative}
.cfi label{display:block;font-size:9.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;color:var(--tx3)}
.cfi b{display:block;font-family:var(--serif);font-size:17px;font-weight:700;margin-top:3px;letter-spacing:-.2px}
.cfi em{display:block;font-style:normal;font-size:10px;color:var(--tx3);margin-top:2px}
.cfi .op{position:absolute;right:-13px;top:50%;transform:translateY(-50%);z-index:3;width:20px;height:20px;
 border-radius:50%;background:var(--paper);border:1px solid var(--line);font-size:12px;font-weight:700;
 color:var(--tx3);display:flex;align-items:center;justify-content:center}
.cfi.plus{background:var(--drb);border-color:var(--drl)}.cfi.plus b{color:var(--drk)}
.cfi.minus{background:var(--crb);border-color:var(--crl)}.cfi.minus b{color:var(--cr)}
.cfi.eq{background:linear-gradient(135deg,var(--cream),var(--cream2));border-color:#E4D9BC}
.cfi.eq b{color:var(--gold)}
@media(max-width:900px){.cfi .op{display:none}}

/* T-format cash book */
.cbook{display:grid;grid-template-columns:1fr 1fr;gap:0;border:1px solid var(--line);border-radius:9px;overflow:hidden;background:var(--paper)}
.cbside{display:flex;flex-direction:column;min-width:0}
.cbside+.cbside{border-left:2px solid var(--line)}
.cbhd{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 11px;
 font-size:11px;font-weight:700;letter-spacing:1.3px;text-transform:uppercase}
.cbside.dr .cbhd{background:var(--drk);color:#fff}
.cbside.cr .cbhd{background:var(--cr);color:#fff}
.cbhd .cbn{font-size:10px;font-weight:600;letter-spacing:.4px;opacity:.9;text-transform:none}
.cbt{width:100%;border-collapse:collapse;font-size:12px;table-layout:fixed}
.cbt th{font-size:9.5px;font-weight:700;letter-spacing:.7px;text-transform:uppercase;color:var(--tx3);
 text-align:left;padding:6px 9px;background:var(--grey1);border-bottom:1px solid var(--line);white-space:nowrap}
.cbt th.r,.cbt td.r{text-align:right}
.cbt td{padding:6px 9px;border-bottom:1px solid var(--hair);vertical-align:top;line-height:1.3}
.cbt tbody tr:nth-child(even){background:var(--zebra)}
.cbside.cr .cbt tbody tr:nth-child(even){background:#FDF7F6}
.cbt .pt{font-weight:600;color:var(--tx);display:block;overflow-wrap:anywhere}
.cbt .pc{display:block;font-size:10px;color:var(--tx3);margin-top:1px}
.cbt .pr{display:block;font-size:9.5px;color:var(--tx3);margin-top:1px;font-family:ui-monospace,Consolas,monospace}
.cbt .amt{font-variant-numeric:tabular-nums;font-weight:700;white-space:nowrap}
.cbside.dr .cbt .amt{color:var(--drk)}
.cbside.cr .cbt .amt{color:var(--cr)}
.cbt tr.bf td{background:var(--cream);font-weight:700}
.cbt tr.bf .pt{color:var(--gold)}
.cbside.dr .cbt tr.bf .amt,.cbside.cr .cbt tr.bf .amt{color:var(--gold)}
.cbt tfoot td{padding:8px 9px;font-weight:700;font-size:12.5px;border-top:2px solid var(--line);background:var(--grey1)}
.cbside.dr .cbt tfoot td{background:var(--drb);color:var(--drk)}
.cbside.cr .cbt tfoot td{background:var(--crb);color:var(--cr)}
.cbempty{padding:16px 11px;font-size:11.5px;color:var(--tx3)}
.cbwrap{max-height:520px;overflow-y:auto}
.cbfoot{display:flex;flex-wrap:wrap;gap:9px;align-items:center;justify-content:space-between;
 padding:9px 12px;margin-top:-1px;border:1px solid var(--line);border-top:0;border-radius:0 0 9px 9px;background:var(--cream)}
.cbfoot .cbf{font-size:11.5px;color:var(--tx2)}
.cbfoot .cbf b{font-size:13px;color:var(--dg);font-variant-numeric:tabular-nums}
.cbfoot .cbf b.neg{color:var(--cr)}
@media(max-width:820px){.cbook{grid-template-columns:1fr}.cbside+.cbside{border-left:0;border-top:2px solid var(--line)}}

/* pay-mode card */
.pmcard{border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden}
.pmhd{display:flex;flex-wrap:wrap;gap:10px;align-items:baseline;justify-content:space-between;padding:10px 13px;
 background:linear-gradient(100deg,var(--dg),var(--dg2));color:#fff}
.pmhd h4{font-size:13.5px;color:#fff;letter-spacing:.6px}
.pmhd span{font-size:10.5px;color:var(--lg2)}
.pmt{width:100%;border-collapse:collapse;font-size:12.5px}
.pmt th{font-size:9.5px;font-weight:700;letter-spacing:.7px;text-transform:uppercase;color:var(--tx3);
 text-align:left;padding:7px 11px;background:var(--grey1);border-bottom:1px solid var(--line);white-space:nowrap}
.pmt th.r,.pmt td.r{text-align:right}
.pmt td{padding:7px 11px;border-bottom:1px solid var(--hair);font-variant-numeric:tabular-nums}
.pmt tbody tr:nth-child(even){background:var(--zebra)}
.pmt tbody tr:hover{background:var(--drb)}
.pmt .pmn{font-weight:700;color:var(--tx)}
.pmt .pms{display:block;font-size:10px;color:var(--tx3);font-weight:400}
.pmt .gr{color:var(--drk);font-weight:700}
.pmt .rd{color:var(--cr);font-weight:700}
.pmt tfoot td{padding:9px 11px;font-weight:700;background:var(--cream);border-top:2px solid var(--line);color:var(--dg)}
.pmbar{height:6px;border-radius:4px;background:var(--grey2);overflow:hidden;min-width:70px}
.pmbar i{display:block;height:100%;background:linear-gradient(90deg,var(--mg),var(--lg))}
.gtag{display:inline-block;font-size:10px;font-weight:700;padding:1px 6px;border-radius:4px;
 background:var(--drb);color:var(--drk);border:1px solid var(--drl)}
.rtag{display:inline-block;font-size:10px;font-weight:700;padding:1px 6px;border-radius:4px;
 background:var(--crb);color:var(--cr);border:1px solid var(--crl)}
td.gr,td.grn{color:var(--drk);font-weight:700}
td.rd{color:var(--cr);font-weight:700}

.winbody{padding:20px;background:var(--canvas)}

