/* ============================================================
   LIFE MASTER REPORT SYSTEM — DATA LAYER (seeded, reproducible)
   ============================================================ */
let SEED=20260725;
function R(){SEED=(SEED*1664525+1013904223)%4294967296;return SEED/4294967296;}
const ri=(a,b)=>a+Math.floor(R()*(b-a+1));
const pk=a=>a[Math.floor(R()*a.length)];
const rf=(a,b,d=1)=>+(a+R()*(b-a)).toFixed(d);
const chance=p=>R()<p;

const TODAY=(function(){var n=new Date();return new Date(n.getFullYear(),n.getMonth(),n.getDate());})();
const MN=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const dAdd=(d,n)=>{const x=new Date(d);x.setDate(x.getDate()+n);return x;};
const ds=d=>`${String(d.getDate()).padStart(2,"0")}-${MN[d.getMonth()]}-${String(d.getFullYear()).slice(2)}`;
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
const ym=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;
const ymL=k=>MN[+k.slice(5)-1]+" "+k.slice(0,4);
const dif=(a,b)=>Math.round((b-a)/864e5);
function ageStr(from,to=TODAY){let y=to.getFullYear()-from.getFullYear(),m=to.getMonth()-from.getMonth(),d=to.getDate()-from.getDate();
 if(d<0){m--;d+=30;} if(m<0){y--;m+=12;} return y+"y "+m+"m "+d+"d";}
const IN=n=>{n=Math.round(n||0);const s=String(Math.abs(n));let l=s.slice(-3),o=s.slice(0,-3);if(o)l=o.replace(/\B(?=(\d{2})+(?!\d))/g,",")+","+l;return (n<0?"-":"")+l;};
let money=n=>"\u20B9"+IN(n);
const pct=(a,b)=>b?(a/b*100).toFixed(1):"0.0";

/* ---------- MASTERS ---------- */
const CLUSTERS=[{id:"TG",n:"Telangana Main Cluster",head:"Preethi"},{id:"AP",n:"Andhra Cluster",head:"Viveka"}];
const BRANCHES=[
 ["KUK","Kukatpally","Hyderabad","TG"],["AMP","Ameerpet","Hyderabad","TG"],["SEC","Secunderabad","Hyderabad","TG"],
 ["DSN","Dilsukhnagar","Hyderabad","TG"],["GCB","Gachibowli","Hyderabad","TG"],["KMP","Kompally","Hyderabad","TG"],
 ["LBN","LB Nagar","Hyderabad","TG"],["DWK","Dwaraka Nagar","Visakhapatnam","AP"],["MVP","MVP Colony","Visakhapatnam","AP"],
 ["BZA","Benz Circle","Vijayawada","AP"],["NLR","Trunk Road","Nellore","AP"]];
const BR=BRANCHES.map(b=>b[0]);
const bName=c=>{const b=BRANCHES.find(x=>x[0]===c);return b?b[1]:c;};
const bFull=c=>{const b=BRANCHES.find(x=>x[0]===c);return b?b[0]+" \u2014 "+b[1]+", "+b[2]:c;};
const bCity=c=>{const b=BRANCHES.find(x=>x[0]===c);return b?b[2]:"";};
const bClu=c=>{const b=BRANCHES.find(x=>x[0]===c);return b?b[3]:"";};

const CATS={
 "SLIMMING":["Inch Loss Therapy","Weight Loss Program","Cellulite Reduction","Body Contouring","Ultrasonic Cavitation","Lipolysis Injection","Diet & Nutrition Plan"],
 "SKIN":["Hydra Facial","Chemical Peel","Medi Facial","Anti-Acne Program","Pigmentation Program","Laser Toning","Carbon Peel","MNRF Treatment"],
 "HAIR":["PRP Therapy","GFC Therapy","Mesotherapy","Hair Spa","Anti-Dandruff Program","Hair Fall Program","Scalp Detox"],
 "LASER":["Full Body LHR","Face LHR","Underarm LHR","Bikini LHR","Legs LHR","Arms LHR"],
 "HAIR TRANSPLANT":["FUE Transplant","FUT Transplant","Beard Transplant","Eyebrow Transplant"],
 "LIFE RISE":["Clinical Nutrition","Diabetic Reversal","PCOS Program","Thyroid Program","Gut Health Program","Post-Natal Program"]};
const CATL=Object.keys(CATS);
const CATPRICE={"SLIMMING":[35000,180000],"SKIN":[12000,90000],"HAIR":[15000,120000],"LASER":[18000,140000],"HAIR TRANSPLANT":[80000,320000],"LIFE RISE":[9000,60000]};
const SOURCES=["Digital \u2014 Meta","Digital \u2014 Google","Walk-In","Referral","Call Centre","Corporate Tie-Up","Camp / Event","Re-Booking"];
const CAMPAIGNS={"Digital \u2014 Meta":["Meta \u2014 Summer Slim","Meta \u2014 Skin Glow","Meta \u2014 Hair Revival","Meta \u2014 Lead Gen Always On"],
 "Digital \u2014 Google":["Google \u2014 Search Brand","Google \u2014 Search Generic","Google \u2014 PMax Clinic","Google \u2014 Display Remarket"],
 "Walk-In":["Signage & Footfall"],"Referral":["Client Referral Scheme","Doctor Referral"],"Call Centre":["Outbound DB Recall","Missed Follow-Up Revival"],
 "Corporate Tie-Up":["IT Park Wellness","Bank Staff Package"],"Camp / Event":["Mall Activation","Society Health Camp","College Camp"],"Re-Booking":["Existing Client Upsell"]};
const MEDS=["None","Hypothyroid","PCOS / PCOD","Type-2 Diabetes","Hypertension","Insulin Resistance","Vitamin D Deficiency","Anaemia","Post-Natal","Cervical Spondylosis","Fatty Liver","Migraine"];
const PAYM=["Cash","UPI","Card \u2014 Credit","Card \u2014 Debit","Bank Transfer","EMI / Loan","Cheque"];
const AGEG=["18-25","26-35","36-45","46-55","56+"];
const agBand=a=>a<=25?"18-25":a<=35?"26-35":a<=45?"36-45":a<=55?"46-55":"56+";

const FN_M=["Rajesh","Srinivas","Karthik","Naveen","Praveen","Vamsi","Rakesh","Sandeep","Kiran","Anil","Mahesh","Ravi","Sai","Bhargav","Nithin","Ramesh","Arun","Suresh","Vikram","Harsha","Chaitanya","Sudhir","Manoj","Deepak","Girish","Yashwanth","Uday","Pradeep"];
const FN_F=["Sravani","Divya","Anusha","Keerthi","Swathi","Lakshmi","Padma","Sneha","Harika","Meghana","Rachana","Pallavi","Nandini","Sirisha","Vaishnavi","Bhavana","Ramya","Shirisha","Manasa","Deepika","Aparna","Sushma","Jyothi","Kavya","Tejaswi","Madhuri","Sowmya","Haritha"];
const LN=["Reddy","Rao","Naidu","Sharma","Kumar","Varma","Prasad","Chowdary","Goud","Yadav","Shetty","Raju","Murthy","Babu","Krishna","Sastry","Pillai","Nair","Menon","Patel","Jain","Agarwal","Bose","Das","Singh"];
const nm=g=>(g==="Male"?pk(FN_M):pk(FN_F))+" "+pk(LN);

const DEPTS=["Sales & Counselling","Clinical \u2014 Slimming","Clinical \u2014 Dermat","Clinical \u2014 Hair","Front Office","Call Centre","Accounts","Stock & Purchase","Housekeeping","Management"];
const DESIG={"Sales & Counselling":["Business Development Executive","Senior Counsellor","Centre Manager"],
 "Clinical \u2014 Slimming":["Dietician","Senior Dietician","Slimming Therapist"],
 "Clinical \u2014 Dermat":["Dermatologist","Skin Therapist","Laser Technician"],
 "Clinical \u2014 Hair":["Trichologist","Hair Transplant Surgeon","HT Technician"],
 "Front Office":["Receptionist","Front Office Executive"],"Call Centre":["Call Centre Agent","CC Team Leader"],
 "Accounts":["Accounts Executive","Branch Accountant"],"Stock & Purchase":["Stock In-Charge","Purchase Executive"],
 "Housekeeping":["Housekeeping Attendant","Facility Supervisor"],"Management":["Cluster Head","Operations Manager","Audit Executive"]};
const QUAL=["B.Sc Nutrition","M.Sc Food & Nutrition","B.Sc Cosmetology","MBBS, MD (DVL)","MBBS, DNB","B.Pharm","MBA \u2014 Marketing","B.Com","M.Com","B.Tech","Diploma in Beauty Therapy","BPT \u2014 Physiotherapy","B.A","Intermediate","MBA \u2014 HR"];
const PREVORG=["Kaya Skin Clinic","VLCC","Naturals Salon & Spa","Oliva Clinic","Apollo Cosmetic","Bodycraft","Richfeel","Dr. Agarwal's","Personal Point","Fresh Graduate","Tvacha Clinic","Vcare"];
const BLOOD=["O+","A+","B+","AB+","O-","B-","A-"];
const MARIT=["Single","Married"];

/* ---------- EMPLOYEES ---------- */
const EMP=[];
(function(){let n=1;
 BR.forEach(b=>{
  const mix=[["Sales & Counselling",3],["Clinical \u2014 Slimming",3],["Clinical \u2014 Dermat",2],["Clinical \u2014 Hair",1],["Front Office",1],["Call Centre",1],["Accounts",1],["Stock & Purchase",1],["Housekeeping",1]];
  mix.forEach(([dp,c])=>{for(let i=0;i<c;i++){
   const g=chance(.62)?"Female":"Male",name=nm(g),dg=pk(DESIG[dp]);
   const joinD=dAdd(TODAY,-ri(60,2400)),dob=new Date(TODAY.getFullYear()-ri(21,48),ri(0,11),ri(1,28));
   const prev=chance(.7)?ri(1,3):0;
   EMP.push({id:"LEMP"+String(n).padStart(4,"0"),n:name,g,dob,br:b,dept:dp,dg,
    ph:"9"+ri(1,8)+String(ri(10000000,99999999)),em:name.split(" ")[0].toLowerCase()+n+"@lifescc.com",
    join:joinD,qual:pk(QUAL),blood:pk(BLOOD),mar:pk(MARIT),
    prevOrg:prev?pk(PREVORG):"Fresher at joining",prevYr:prev,
    sal:ri(14,68)*1000,bank:"HDFC \u2014 XXXX"+ri(1000,9999),pan:"ABCPX"+ri(1000,9999)+"K",
    uan:"1012"+ri(10000000,99999999),esi:chance(.6)?"41"+ri(10000000,99999999):"\u2014",
    addr:pk(["Flat "+ri(101,706),"H.No "+ri(1,20)+"-"+ri(1,99)])+", "+pk(["Miyapur","Kondapur","Alwal","Malkajgiri","Nizampet","Madhapur","Seethammadhara","Patamata","Dargamitta"])+", "+bCity(b),
    emg:nm(chance(.5)?"Male":"Female")+" \u2014 9"+ri(1,8)+String(ri(10000000,99999999)),
    st:chance(.93)?"Active":"Exited",exit:null,
    shift:pk(["10:00 - 19:00","09:30 - 18:30","11:00 - 20:00"]),
    rep:null});
   n++;}});
 });
 EMP.forEach(e=>{if(e.st==="Exited")e.exit=dAdd(TODAY,-ri(5,300));});
 // reporting
 EMP.forEach(e=>{const cm=EMP.find(x=>x.br===e.br&&x.dg==="Centre Manager");e.rep=cm&&cm.id!==e.id?cm.n+" (Centre Manager)":"Preethi (Cluster Head)";});
})();
const EMPA=EMP.filter(e=>e.st==="Active");
const empBy=id=>EMP.find(e=>e.id===id)||{n:"\u2014",dg:"\u2014",br:"\u2014"};
const salesEmp=b=>EMPA.filter(e=>e.br===b&&e.dept==="Sales & Counselling");
const clinEmp=(b,cat)=>{const m={"SLIMMING":"Clinical \u2014 Slimming","SKIN":"Clinical \u2014 Dermat","LASER":"Clinical \u2014 Dermat","HAIR":"Clinical \u2014 Hair","HAIR TRANSPLANT":"Clinical \u2014 Hair","LIFE RISE":"Clinical \u2014 Slimming"};
 const l=EMPA.filter(e=>e.br===b&&e.dept===m[cat]);return l.length?pk(l):pk(EMPA.filter(e=>e.br===b));};
const ccAgents=EMPA.filter(e=>e.dept==="Call Centre");

/* ---------- CLIENTS ---------- */
const CLI=[];
(function(){for(let i=1;i<=460;i++){
 const g=chance(.71)?"Female":chance(.96)?"Male":"Other",name=nm(g==="Other"?"Female":g),b=pk(BR);
 const age=ri(19,62),reg=dAdd(TODAY,-ri(3,900)),src=pk(SOURCES);
 const cats=[];const nc=chance(.34)?2:chance(.08)?3:1;
 while(cats.length<nc){const c=pk(CATL);if(!cats.includes(c))cats.push(c);}
 const h=ri(148,182),jw=g==="Male"?rf(68,108):rf(56,98);
 const hasSlim=cats.includes("SLIMMING")||cats.includes("LIFE RISE");
 const loss=hasSlim?rf(1.5,17):rf(0,2.5);
 const cw=+(jw-loss).toFixed(1),tw=+(jw-(hasSlim?rf(8,22):2)).toFixed(1);
 const med=chance(.42)?pk(MEDS.slice(1)):"None";
 const cons=pk(salesEmp(b).length?salesEmp(b):EMPA);
 CLI.push({id:"LC"+String(10000+i),uhid:"UH"+b+String(1000+i),n:name,g,age,ag:agBand(age),
  ph:"9"+ri(1,8)+String(ri(10000000,99999999)),alt:chance(.35)?"8"+ri(1,8)+String(ri(10000000,99999999)):"\u2014",
  br:b,city:bCity(b),reg,src,camp:pk(CAMPAIGNS[src]),cats,cat:cats[0],
  ht:h,jw,cw,tw,loss:+loss.toFixed(1),inch:hasSlim?rf(2,26):0,
  bmi:+(cw/((h/100)**2)).toFixed(1),fat:rf(21,42),
  med,alle:chance(.18)?pk(["Sulfa drugs","Peanuts","Latex","Dust / Pollen"]):"None",
  cons:cons.id,exec:pk(salesEmp(b).length?salesEmp(b):EMPA).id,
  occ:pk(["Software Engineer","Home Maker","Teacher","Business","Doctor","Bank Officer","Student","Govt Employee","Sales Manager","Self Employed"]),
  em:name.split(" ")[0].toLowerCase()+i+"@gmail.com",
  addr:pk(["Flat "+ri(101,908),"Plot "+ri(1,220)])+", "+pk(["Kukatpally","Madhapur","Kothapet","Kondapur","Suryabagh","Labbipet","Magunta Layout"])+", "+bCity(b),
  st:"Active",vis:0,lastV:null,nextA:null,bill:0,paid:0,due:0});
}})();
const cliBy=id=>CLI.find(c=>c.id===id);

/* ---------- INVOICES ---------- */
const INV=[];
(function(){let n=1;
 CLI.forEach(c=>{
  const cnt=chance(.2)?3:chance(.45)?2:1;
  for(let k=0;k<cnt;k++){
   const cat=c.cats[Math.min(k,c.cats.length-1)],tr=pk(CATS[cat]),pr=CATPRICE[cat];
   const d=dAdd(c.reg,ri(0,Math.max(1,dif(c.reg,TODAY)-2)));
   const gross=ri(pr[0],pr[1]),dsc=chance(.72)?Math.round(gross*rf(.05,.32,2)):0;
   const net=gross-dsc,gst=Math.round(net*.05),tot=net+gst;
   const paid=chance(.52)?tot:Math.round(tot*rf(.25,.9,2));
   const sess=cat==="HAIR TRANSPLANT"?1:ri(6,32);
   INV.push({no:"LIFE/"+d.getFullYear()+"/"+String(n).padStart(5,"0"),d,cli:c.id,br:c.br,cat,tr,
    sess,used:0,gross,dsc,dscp:+(dsc/gross*100).toFixed(1),net,gst,tot,paid,due:tot-paid,
    pm:pk(PAYM),emp:chance(.85)?c.exec:pk(salesEmp(c.br).length?salesEmp(c.br):EMPA).id,
    bt:pk(["Direct Walk-In","CC Walk-In","Referral","Re-Booking"]),
    appr:dsc>net*.2?pk(["COO \u2014 KBP","Cluster Head","Centre Manager"]):"Centre Manager",
    st:paid>=tot?"Fully Paid":paid>0?"Part Paid":"Unpaid"});
   n++;}
 });
 INV.sort((a,b)=>a.d-b.d);
 CLI.forEach(c=>{const l=INV.filter(i=>i.cli===c.id);
  c.bill=l.reduce((s,i)=>s+i.tot,0);c.paid=l.reduce((s,i)=>s+i.paid,0);c.due=c.bill-c.paid;});
})();
const invBy=no=>INV.find(i=>i.no===no);
const DUESLAB=[[0,1,"\u20B90 \u2014 1,000"],[1000,25000,"\u20B91k \u2014 25k"],[25000,50000,"\u20B925k \u2014 50k"],[50000,100000,"\u20B950k \u2014 1L"],[100000,200000,"\u20B91L \u2014 2L"],[200000,1e9,"\u20B92L +"]];
const dueSlab=v=>v<=0?"No Due":(DUESLAB.find(s=>v>=s[0]&&v<s[1])||DUESLAB[5])[2];

/* ---------- SESSIONS / SERVICE EXECUTIONS ---------- */
const SESS=[];
(function(){let n=1;
 INV.forEach(iv=>{
  const done=Math.min(iv.sess,Math.round(iv.sess*rf(.15,1,2)));iv.used=done;
  const span=Math.max(4,dif(iv.d,TODAY));
  for(let k=0;k<done;k++){
   const d=dAdd(iv.d,Math.round(span*(k+1)/(done+1))+ri(-2,2));
   if(d>TODAY)continue;
   const c=cliBy(iv.cli),th=clinEmp(iv.br,iv.cat);
   const inH=ri(9,18),inM=pk([0,15,30,45]),dur=iv.cat==="HAIR TRANSPLANT"?ri(240,420):ri(35,110);
   const st=new Date(2020,0,1,inH,inM),en=new Date(st.getTime()+dur*6e4);
   const w0=+(c.jw-(c.loss*k/Math.max(1,done))).toFixed(1),w1=+(c.jw-(c.loss*(k+1)/Math.max(1,done))).toFixed(1);
   SESS.push({id:"SES"+String(n).padStart(5,"0"),d,br:iv.br,cli:iv.cli,inv:iv.no,cat:iv.cat,tr:iv.tr,
    sno:k+1,tot:iv.sess,th:th.id,
    inT:String(inH).padStart(2,"0")+":"+String(inM).padStart(2,"0"),
    outT:String(en.getHours()).padStart(2,"0")+":"+String(en.getMinutes()).padStart(2,"0"),
    dur,bp:ri(102,138)+"/"+ri(66,90),pulse:ri(64,96),
    w0,w1,inch:iv.cat==="SLIMMING"?rf(.2,1.4):0,
    bca:chance(.5)?"Done":"\u2014",ph:chance(.66)?"Yes":"No",
    appt:chance(.68),stt:chance(.94)?"Completed":pk(["Partially Done","Client Left Early"]),
    imp:ri(35,96),grade:pk(["I","II","III","IV","V"]),
    prod:pk(["Slim Gel 30ml","Peel Solution 15ml","PRP Kit","GFC Kit","Serum C 10ml","Cooling Gel 50ml","Numbing Cream 20g"]),
    rem:pk(["Client comfortable","Mild redness observed","Good response","Advised hydration","No adverse reaction","Follow diet strictly"])});
   n++;}
 });
 SESS.sort((a,b)=>a.d-b.d);
 CLI.forEach(c=>{const l=SESS.filter(s=>s.cli===c.id);c.vis=l.length;c.lastV=l.length?l[l.length-1].d:null;
  if(c.lastV&&dif(c.lastV,TODAY)>45)c.st="In-Active (45+ days)";});
})();

/* ---------- APPOINTMENTS ---------- */
const APPT=[],AST=["Visited","Postponed","Cancelled","No Response","Scheduled"];
(function(){let n=1;
