/* ---------- BRANCH CASH BOOK (day-wise debit / credit ledger) ---------- */
const CB_DAYS=950;                       /* how far back the cash book runs */
const RCPT_HEADS=[
 ["Cash Sale","Sales \u2014 Cash Collection"],
 ["Cash Receipt \u2014 Due Collection","Receipts \u2014 Old Balance"],
 ["Cash Receipt \u2014 Part Payment","Receipts \u2014 Part Payment"],
 ["Retail / Product Sale \u2014 Cash","Sales \u2014 Retail Counter"],
 ["Consultation Fee \u2014 Cash","Sales \u2014 Consultation"],
 ["Cash Received From MD","Current Liability \u2014 MD Account"],
 ["Petty Cash Received from HO","Current Liability \u2014 Petty Cash"],
 ["Cash Received from Other Branch","Inter-Branch Transfer In"]];
const PAY_HEADS=[
 ["Cash Handover to HO","Fund Transfer \u2014 Head Office"],
 ["Bank Deposit \u2014 Cash","Fund Transfer \u2014 Bank"],
 ["Expenditure \u2014 Housekeeping","Facility"],
 ["Expenditure \u2014 Water & Sanitation","Utilities"],
 ["Expenditure \u2014 Printing & Stationery","Admin"],
 ["Expenditure \u2014 Travel & Conveyance","Admin"],
 ["Expenditure \u2014 Staff Refreshments","Admin"],
 ["Expenditure \u2014 Consumables Local Purchase","Direct Cost"],
 ["Expenditure \u2014 Repairs & Maintenance","Facility"],
 ["Expenditure \u2014 Courier & Postage","Admin"],
 ["Expenditure \u2014 Internet & Phone Recharge","Utilities"],
 ["Staff Advance Paid","Manpower"],
 ["Incentive Payout \u2014 Cash","Manpower"],
 ["Refund to Client \u2014 Cash","Sales Return"],
 ["Cash Sent to Other Branch","Inter-Branch Transfer Out"]];
const CB_MODE=["Cash"];
const CASHBOOK=[];
(function(){
 let n=1;
 let SEQ=0;
 const V=p=>p+"/26/"+String(n++).padStart(5,"0");
 const EMPBR={};BR.forEach(b=>{const l=EMPA.filter(e=>e.br===b);EMPBR[b]=l.length?l:EMPA;});
 const OTHBR={};BR.forEach(b=>OTHBR[b]=BR.filter(x=>x!==b));
 const key=(b,d)=>b+"|"+iso(d);
 /* --- index the real books by branch + day so the cash book ties back to them --- */
 const saleMap={},expMap={},dueMap={};
 INV.forEach(i=>{if(i.pm!=="Cash"||i.paid<=0)return;if(dif(i.d,TODAY)>CB_DAYS)return;
  (saleMap[key(i.br,i.d)]=saleMap[key(i.br,i.d)]||[]).push(i);});
 EXP.forEach(e=>{if(e.pm!=="Cash")return;if(dif(e.d,TODAY)>CB_DAYS)return;
  (expMap[key(e.br,e.d)]=expMap[key(e.br,e.d)]||[]).push(e);});
 INV.filter(i=>i.due>0).forEach(i=>{if(!chance(.34))return;
  const d=dAdd(i.d,ri(5,120));if(d>TODAY||dif(d,TODAY)>CB_DAYS)return;
  (dueMap[key(i.br,d)]=dueMap[key(i.br,d)]||[]).push(i);});

 BR.forEach(b=>{
  /* opening cash box balance carried into the first day of the book */
  let cash=ri(18000,95000);
  CASHBOOK.push({id:V("OPN"),br:b,d:dAdd(TODAY,-CB_DAYS),dr:cash,cr:0,
   head:"Opening Balance b/f",cat:"Opening \u2014 Cash in Hand",party:"Branch Cash Box",
   ref:"OPN/"+b,mode:"Cash",kind:"open"});

  for(let k=CB_DAYS-1;k>=0;k--){
   const d=dAdd(TODAY,-k),kk=key(b,d),sun=d.getDay()===0;
   if(sun&&chance(.55))continue;                       /* quieter Sundays */
   const busy=dif(d,TODAY)<=200;
   let inToday=0;

   /* --- DEBIT: cash invoices billed that day --- */
   (saleMap[kk]||[]).forEach(i=>{const c=cliBy(i.cli);
    cash+=i.paid;inToday+=i.paid;
    CASHBOOK.push({id:V("RCP"),br:b,d,dr:i.paid,cr:0,
     head:"Cash Sale \u2014 "+(c?c.n:"Client"),cat:"Sales \u2014 Cash Collection",
     party:(c?c.n:"Client")+" \u00B7 "+(CATFULL[i.cat]||i.cat),
     ref:i.no,mode:"Cash",kind:"sale",inv:i.no,cli:i.cli});});

   /* --- DEBIT: old balances recovered in cash --- */
   (dueMap[kk]||[]).forEach(i=>{const c=cliBy(i.cli);
    const amt=Math.max(500,Math.round(i.due*rf(.12,.7,2)));
    cash+=amt;inToday+=amt;
    CASHBOOK.push({id:V("RCP"),br:b,d,dr:amt,cr:0,
     head:"Cash Receipt \u2014 Due Collection",cat:"Receipts \u2014 Old Balance",
     party:(c?c.n:"Client")+" \u00B7 "+(CATFULL[i.cat]||i.cat),
     ref:i.no,mode:"Cash",kind:"receipt",inv:i.no,cli:i.cli});});

   /* --- DEBIT: counter receipts, part payments, consultation, retail --- */
   for(let r=0;r<(busy?ri(1,3):ri(0,2));r++){
    const h=pk([RCPT_HEADS[2],RCPT_HEADS[3],RCPT_HEADS[4]]);
    const amt=ri(600,14000);cash+=amt;inToday+=amt;
    CASHBOOK.push({id:V("RCP"),br:b,d,dr:amt,cr:0,head:h[0],cat:h[1],
     party:"Front office counter",ref:"RCV/"+b+"/"+ri(1000,9999),mode:"Cash",kind:"receipt"});}

   /* --- CREDIT: real expense vouchers paid in cash that day --- */
   (expMap[kk]||[]).forEach(e=>{
    const amt=Math.min(e.amt,Math.max(0,cash));        /* a branch cannot pay cash it does not hold */
    if(amt<=0)return;cash-=amt;
    CASHBOOK.push({id:V("PAY"),br:b,d,dr:0,cr:amt,
     head:"Expenditure \u2014 "+e.head,cat:e.cat,party:e.narr,ref:e.v,mode:"Cash",
     kind:"expense",exph:e.head});});

   /* --- CREDIT: petty payments, advances, incentives, refunds --- */
   for(let p=0;p<(busy?ri(1,3):ri(0,2));p++){
    const h=pk(PAY_HEADS.slice(2,14));
    let amt=h[0].indexOf("Staff Advance")===0?ri(2000,25000)
      :h[0].indexOf("Incentive")===0?ri(3000,45000)
      :h[0].indexOf("Refund")===0?ri(2000,40000):ri(350,12000);
    amt=Math.min(amt,Math.max(0,Math.round(cash*.35)));
    if(amt<200)continue;cash-=amt;
    const em=pk(EMPBR[b]);
    CASHBOOK.push({id:V("PAY"),br:b,d,dr:0,cr:amt,head:h[0],cat:h[1],
     party:h[0].indexOf("Staff Advance")===0||h[0].indexOf("Incentive")===0?em.n+" \u00B7 "+em.dg
      :h[0].indexOf("Refund")===0?"Client refund \u2014 approved by Centre Manager"
      :pk(["Local vendor","Facility vendor","Petty purchase","Utility counter"]),
     ref:"PV/"+b+"/"+ri(1000,9999),mode:"Cash",
     kind:h[0].indexOf("Refund")===0?"refund":
      (h[0].indexOf("Staff Advance")===0||h[0].indexOf("Incentive")===0?"payout":"expense")});}

   /* --- CREDIT: handover / bank deposit sweeps the surplus, never the float --- */
   const FLOAT=ri(12000,30000);                        /* cash the branch must keep overnight */
   if(cash>FLOAT+15000&&chance(busy?.72:.5)){
    const bank=chance(.45);
    const amt=Math.round((cash-FLOAT)*rf(.55,.95,2));
    if(amt>1000){cash-=amt;
     CASHBOOK.push({id:V("HND"),br:b,d,dr:0,cr:amt,
      head:bank?"Bank Deposit \u2014 Cash":"Cash Handover to HO",
      cat:bank?"Fund Transfer \u2014 Bank":"Fund Transfer \u2014 Head Office",
      party:bank?"HDFC Bank \u00B7 A/c XXXX"+ri(1000,9999):"Head Office \u2014 Accounts Dept",
      ref:(bank?"BD/":"HO/")+b+"/"+ri(1000,9999),mode:"Cash",kind:"handover"});}}

   /* --- DEBIT: top-up from MD or HO when the branch runs short --- */
   if(cash<8000&&chance(.5)){
    const md=chance(.4);
    const amt=md?ri(20000,150000):ri(3000,25000);cash+=amt;
    CASHBOOK.push({id:V("RCP"),br:b,d,dr:amt,cr:0,
     head:md?"Cash Received From MD":"Petty Cash Received from HO",
     cat:md?"Current Liability \u2014 MD Account":"Current Liability \u2014 Petty Cash",
     party:md?"KP Sir \u2014 MD Account":"Head Office \u2014 Accounts Dept",
     ref:(md?"MD/":"PC/")+b+"/"+ri(1000,9999),mode:"Cash",kind:"receipt"});}

   /* --- inter-branch cash movement, occasionally --- */
   if(chance(.012)&&cash>40000){
