  c.media=c.src;
  c.card="LC-"+c.br+"-"+String(1000+n).padStart(5,"0");n++;
  c.refBy=chance(.24)?pk(CLI).n:"\u2014";
  c.refCount=CLI.filter(x=>x.refBy===c.n).length;
  const sold=iv.reduce((s,i)=>s+i.sess,0),used=iv.reduce((s,i)=>s+i.used,0);
  c.sold=sold;c.used=used;c.balSess=sold-used;
  c.invCount=iv.length;
  c.plans=iv.length;
  c.validDays=iv.length?ri(180,540):0;
  c.validTill=c.joined?dAdd(c.joined,c.validDays):null;
  c.dnd=chance(.12);
  c.pref=pk(PREFC)[0];
  c.zeroSess=used===0;
  c.bkdSess=ap.filter(a=>a.st!=="Cancelled").length;
  c.bca=ss.filter(s=>s.bca==="Done").length;
  c.fups=ri(0,14);
  c.dietFups=c.cats.includes("SLIMMING")||c.cats.includes("LIFE RISE")?ri(0,11):0;
  c.fbCount=FB.filter(f=>f.cli===c.id).length;
