   ? (EMPA.filter(e=>e.br===c.br&&e.dg.includes("Dietician"))[0]||empBy(c.cons)).id : null;
  c.rebooked=iv.filter(i=>i.bt==="Re-Booking").length;
  /* card lifecycle */
  const gapDays=ss.length?dif(ss[ss.length-1].d,TODAY):(c.joined?dif(c.joined,TODAY):dif(c.reg,TODAY));
  c.cardExp=c.validTill?c.validTill<TODAY:false;
  /* Open  = card issued, nothing availed yet, still inside validity
     Active = availed and seen within 45 days
     Break  = 45 to 90 days since the last session
     De-Active = beyond 90 days, or the card has expired
     Closed = every session sold has been delivered */
  c.cardSt=!iv.length?"Open":(sold-used)<=0?"Closed":(used===0&&!c.cardExp)?"Open"
   :c.cardExp?"De-Active":gapDays>90?"De-Active":gapDays>45?"Break":"Active";
  c.gapDays=gapDays;
  /* monthly engagement */
  const months=Math.max(1,Math.round(dif(c.reg,TODAY)/30));
  c.avgVisit=+(ss.length/months).toFixed(2);
  c.mApt=+(ap.length/months).toFixed(2);
  c.aptTot=ap.length;
  c.aptVis=ap.filter(a=>a.st==="Visited").length;
  c.aptCan=ap.filter(a=>a.st==="Cancelled").length;
  c.aptPos=ap.filter(a=>a.st==="Postponed").length;
  c.aptNR=ap.filter(a=>a.st==="No Response").length;
  c.lossPct=+pct(c.aptCan+c.aptPos+c.aptNR,ap.length||1);
  c.regularity=c.avgVisit>=3?"Regular":c.avgVisit>=1.5?"Moderate":c.avgVisit>0?"Irregular":"Not started";
  c.pkgDone=sold?+pct(used,sold):0;
  c.breaks=(function(){let g=0;for(let i=1;i<ss.length;i++)if(dif(ss[i-1].d,ss[i].d)>21)g++;return g;})();
  c.status=c.cardSt==="Active"?"Active":c.cardSt==="Break"?"Break":c.cardSt==="Closed"?"Closed":"De-Active";
  c.tenure=months;
 });
})();
