 const o={n:brks.length,max:mx,cur,avg:gaps.length?Math.round(gaps.reduce((a,b)=>a+b,0)/gaps.length):0,
  months:Math.max(1,Math.round(dif(c.reg,TODAY)/30)),sold,used,bal:sold-used,adh:sold?+pct(used,sold):0,st,
