const RIGHT=["m","n","p","md","nd"];
function draw(id){
 const{cols,rows,o}=TB[id];
 const dense=cols.length>=12;
 const M=v=>dense&&AMTMODE!=='F'?mL(v):money(v);
 const fmt=(v,t)=>{
  if(v===undefined||v===null||v==="")return"\u2014";
  if(t==="m")return M(v);if(t==="n")return IN(v);
  if(t==="p")return (+v).toFixed(1)+"%";if(t==="d")return ds(v);return v;};
 const cell=(r,c)=>{
  if(c.t==="h"||c.t==="x")return r[c.k]||"\u2014";
  if(c.t==="md")return D(M(r[c.k]||0),M(r[c.k2]||0),(r[c.k2]||0)>0?"a2":"g");
  if(c.t==="nd")return D(IN(r[c.k]||0),IN(r[c.k2]||0),"g");
  return fmt(r[c.k],c.t);};
 const grouped=rows.some(r=>r._grp);
 const data=rows.filter(r=>!r._grp);
 const tot={};cols.forEach(c=>{if(c.nt===1)return;
  if(["m","n"].includes(c.t))tot[c.k]=data.reduce((s,r)=>s+(+r[c.k]||0),0);
  if(["md","nd"].includes(c.t)){tot[c.k]=data.reduce((s,r)=>s+(+r[c.k]||0),0);tot[c.k2]=data.reduce((s,r)=>s+(+r[c.k2]||0),0);}});
 PSTAT.rows+=data.length;
 const firstM=cols.find(c=>c.t==="m"&&c.nt!==1);
 if(firstM&&tot[firstM.k])PSTAT.val=Math.max(PSTAT.val,tot[firstM.k]);
 const cls=c=>RIGHT.includes(c.t)?" r":"";
 /* group each parent row with its drawer row so pagination keeps them together */
 const units=[];rows.forEach(r=>{
  if(r._grp===3&&units.length)units[units.length-1].push(r);else units.push([r]);});
