function pagBar(id,pg,pages,total,size){
 const btn=(l,to,on,dis)=>`<button ${on?'class="on"':""} ${dis?"disabled":""} onclick="goPage('${id}',${to})">${l}</button>`;
 let nums=[];
 const win=2;let start=Math.max(1,pg-win),end=Math.min(pages,pg+win);
 if(start>1)nums.push(btn(1,1,pg===1));
 if(start>2)nums.push('<span class="pdots">&hellip;</span>');
 for(let i=start;i<=end;i++)nums.push(btn(i,i,pg===i));
 if(end<pages-1)nums.push('<span class="pdots">&hellip;</span>');
 if(end<pages)nums.push(btn(pages,pages,pg===pages));
