 return `<div class="pag"><span class="pinfo">Showing ${IN(from)}\u2013${IN(to)} of ${IN(total)} records</span>
  ${btn("\u2039 Previous",pg-1,false,pg===1)}${nums.join("")}${btn("Next \u203A",pg+1,false,pg===pages)}</div>`;}
