function topPop(t){
 let l=fCLI().slice(),ttl="";
 const pp=c=>APPT.filter(a=>a.cli===c.id&&a.st==="Postponed").length;
 if(t==="drop"){l=l.filter(c=>brk(c.id).st==="Dropped out").sort((a,b)=>brk(b.id).cur-brk(a.id).cur);ttl="Dropped out \u2014 90+ days since last session";}
 else if(t==="lbrk"){l=l.filter(c=>brk(c.id).st==="Long break").sort((a,b)=>brk(b.id).cur-brk(a.id).cur);ttl="Long break \u2014 45 to 90 days";}
 else if(t==="sbrk"){l=l.filter(c=>brk(c.id).st==="Short break").sort((a,b)=>brk(b.id).cur-brk(a.id).cur);ttl="Short break \u2014 21 to 45 days";}
 else if(t==="due"){l=l.filter(c=>c.due>0).sort((a,b)=>b.due-a.due).slice(0,10);ttl="Highest pending dues";}
 else if(t==="bal"){l=l.filter(c=>brk(c.id).bal>0).sort((a,b)=>brk(b.id).bal-brk(a.id).bal).slice(0,10);ttl="Largest unused session balance";}
 else if(t==="h3"){l=l.filter(c=>c.bill>=500000).sort((a,b)=>b.bill-a.bill);ttl="VIP HNI \u2014 \u20B95L and above";}
 else if(t==="h1"){l=l.filter(c=>c.bill>=150000&&c.bill<500000).sort((a,b)=>b.bill-a.bill);ttl="HNI \u2014 \u20B91.5L to \u20B95L";}
 else if(t==="med"){l=l.filter(c=>c.med!=="None").sort((a,b)=>b.bill-a.bill);ttl="Medical high-risk clients";}
 else if(t==="pp"){l.sort((a,b)=>pp(b)-pp(a));l=l.slice(0,10);ttl="Most postponements";}
 else if(t==="cmp"){const ids=FB.filter(f=>f.cmp!=="\u2014").map(f=>f.cli);l=l.filter(c=>ids.includes(c.id)).slice(0,10);ttl="Complaints raised";}
 else if(t==="wl"){l=l.filter(c=>c.loss>0).sort((a,b)=>b.loss-a.loss).slice(0,10);ttl="Best clinical outcome \u2014 weight reduced";}
 else if(t==="mc"){l=l.filter(c=>c.cats.length>1).sort((a,b)=>b.bill-a.bill);ttl="Multi-specialty clients";}
 openM(ttl+" \u2014 "+IN(l.length)+" client(s)",cliTable(l));}

