function clue(v){FV.search=v;SHOWN=true;render();}
function resolveSearch(q){
 const s=q.trim().toLowerCase();if(!s)return[];
 const inv=INV.filter(i=>i.no.toLowerCase().includes(s));
 const byInv=inv.map(i=>cliBy(i.cli)).filter(Boolean);
 const cl=CLI.filter(c=>c.n.toLowerCase().includes(s)||c.uhid.toLowerCase().includes(s)
  ||c.id.toLowerCase().includes(s)||c.ph.includes(s)||(c.alt||"").includes(s)||c.em.toLowerCase().includes(s));
 return [...new Set([...cl,...byInv])];}
