 const totDue=dueL.reduce((s,i)=>s+i.due,0);
 const due90=dueL.filter(i=>dif(i.d,TODAY)>90).reduce((s,i)=>s+i.due,0);
 const unearned=allInv.reduce((s,i)=>s+Math.round(i.tot/i.sess*(i.sess-i.used)),0);
 const base=CLI.filter(c=>brs.includes(c.br));
 const active=base.filter(c=>c.lastV&&dif(c.lastV,TODAY)<=45).length;
 const drop=base.filter(c=>brk(c.id).st==="Dropped out").length;
 const cPend=CONV.filter(x=>brs.includes(x.br)&&x.st!=="Converted");
 const po=PURCH.filter(x=>brs.includes(x.br)&&x.st==="Pending Approval");
 const lvP=LV.filter(x=>brs.includes(x.br)&&x.st==="Pending");
 const bigDisc=iv.filter(i=>i.dscp>30);
 const margin=+pct(net-cost,net||1);
 const weak=scopeBR().map(b=>{const l=iv.filter(i=>i.br===b),e2=ex.filter(x=>x.br===b);
  const n=Math.round(l.reduce((s,i)=>s+i.tot,0)/1.05),c2=e2.reduce((s,x)=>s+x.amt,0);
  return{b,m:+pct(n-c2,n||1),rev:l.reduce((s,i)=>s+i.tot,0)};}).filter(x=>x.m<8);
 const health=Math.round((Math.min(100,collEff)*0.3)+(Math.min(100,margin*2)*0.3)
  +(Math.min(100,+pct(active,base.length||1))*0.25)+(Math.max(0,100-+pct(due90,totDue||1))*0.15));
 const tone=v=>v>=85?"ok":v>=70?"w":"b";
 const tile=(l,v,e)=>`<div class="packtile"><label>${l}</label><b>${v}</b><em>${e||""}</em></div>`;
 const dec=[];
 if(due90>0)dec.push(["Approve escalation on receivables past 90 days",money(due90),"Finance head \u00B7 cluster heads",
  "Hand the "+IN(dueL.filter(i=>dif(i.d,TODAY)>90).length)+" oldest invoices to the recovery desk with a two-week deadline."]);
 if(unearned>0)dec.push(["Clear the undelivered service backlog",money(unearned),"Clinical heads",
  "Schedule the "+IN(allInv.reduce((s,i)=>s+(i.sess-i.used),0))+" sessions already paid for; the liability sits on the books until they are delivered."]);
 if(weak.length)dec.push(["Place weak clinics on a 90-day plan",weak.length+" clinic(s)","COO",
  weak.map(x=>bName(x.b)).join(", ")+" are below an 8% contribution margin."]);
 if(drop)dec.push(["Approve the clinical recall campaign",IN(drop)+" clients","Centre managers",
  "Clients unseen for more than 90 days. Recall them before the packages lapse."]);
 if(cPend.length)dec.push(["Clear pending package conversions",money(cPend.reduce((s,x)=>s+x.cv,0)),"Audit \u2192 COO",
  IN(cPend.length)+" requests are waiting, the oldest for "+(cPend.length?Math.max(...cPend.map(x=>x.days)):0)+" days."]);
 if(bigDisc.length)dec.push(["Ratify discounts above 30%",money(bigDisc.reduce((s,i)=>s+i.dsc,0)),"COO",
  IN(bigDisc.length)+" invoices were written outside the counsellor mandate this period."]);
 if(po.length+lvP.length)dec.push(["Release purchase orders and leave",money(po.reduce((s,x)=>s+x.val,0)),"Purchase \u00B7 centre managers",
  IN(po.length)+" orders and "+IN(lvP.length)+" leave applications are blocked pending approval."]);
 const problem=weak.length?"the "+weak.length+" clinic(s) running below an eight per cent margin"
  :collEff<85?"collection efficiency at "+collEff+"%, short of the 85% benchmark"
  :due90>0?"receivables of "+money(due90)+" sitting past ninety days":"the undelivered service backlog";
 openM("\u{1F4D1} Report Pack \u2014 "+(FV.date==="Custom Range"?rangeLbl():FV.date),
  `<div class="packgrid">
    ${tile("Revenue",money(rev),IN(iv.length)+" invoices")}
    ${tile("Collection efficiency",collEff+"%",money(coll)+" received")}
