/* ---- period grouping helpers ---- */
function baGroup(inr,keyf,labelf,opening){
 const keys=[...new Set(inr.map(keyf))].sort();
 let bal=opening;const out=[];
 keys.forEach(k=>{
  const l=inr.filter(e=>keyf(e)===k);
  const sale=sum(l.filter(isSale),e=>e.dr),rcpt=sum(l.filter(isRcpt),e=>e.dr);
  const othD=sum(l.filter(e=>e.dr>0&&!isSale(e)&&!isRcpt(e)),e=>e.dr);
  const exp=sum(l.filter(isExp),e=>e.cr),hand=sum(l.filter(isHand),e=>e.cr);
  const othC=sum(l.filter(e=>e.cr>0&&!isExp(e)&&!isHand(e)),e=>e.cr);
  const dr=sale+rcpt+othD,cr=exp+hand+othC,op=bal;bal=op+dr-cr;
  out.push({k,label:labelf(l[0],k),n:l.length,op,sale,rcpt,othD,dr,exp,hand,othC,cr,cl:bal,
   d:l[0].d,entries:l});});
 return out;}

