/* ============================================================
   LIVE DATA LAYER  —  report_master_api
   Replaces synthetic INV / CLI / EMP with live ERPNext rows.
   Money + collections + client reports (1,10,12,110-115,20,30)
   run on live data. Session/clinical reports (21,22) are parked.
   ============================================================ */
const LIVE = {
  api: "/api/method/report_master_api",
  loaded: false,
  from: null,
  to: null,
  raw: null
};

/* cost-center ("Vizag - LSACPL") -> short branch CODE we invent (VZG).
   Codes are derived once from the live branch list so the whole
   dashboard (BRANCHES/BR/CFG/clusters) is rebuilt around real data. */
function liveCode(cname){
  const s = (cname||"").toUpperCase().replace(/[^A-Z ]/g,"").trim();
  const parts = s.split(/\s+/).filter(Boolean);
  let code;
  if(parts.length >= 2) code = parts[0][0] + parts[1][0] + (parts[1][1]||"");
  else code = s.slice(0,3);
  return code.slice(0,4) || "BR";
}

/* Andhra / Vizag / Vijayawada / Nellore -> C2, rest -> C1 */
function liveCluster(cname){
  const x = (cname||"").toLowerCase();
  if(x.indexOf("vizag")>-1 || x.indexOf("visakha")>-1 ||
     x.indexOf("vijayawada")>-1 || x.indexOf("benz")>-1 ||
     x.indexOf("nellore")>-1 || x.indexOf("mvp")>-1) return "C2";
  return "C1";
}

/* rebuild BRANCHES/BR/CFG/CC maps from live cost centers */
let CC2CODE = {};   // "Vizag - LSACPL" -> "VZG"
let CODE2CC = {};   // "VZG" -> "Vizag - LSACPL"
let LIVE_COLL = {}; // "CODE|YYYY-MM" -> {raw, after_gst, net_cuts}
let LIVE_TGT = {};  // "CODE|YYYY-MM" -> target amount (live)
let LIVE_ACH = {};  // "CODE|YYYY-MM" -> achieved amount (live, with cuts)
let PAY_BY_INV = {}; // invoice no -> [{pe, mode, d, amt}]
function liveBuildBranches(brs){
  const seen = {};
  const rows = [];
  const c1 = [], c2 = [];
  brs.forEach(b=>{
    let code = liveCode(b.name);
    let base = code, k = 2;
    while(seen[code]){ code = base + k; k++; }
    seen[code] = 1;
    CC2CODE[b.cc] = code;
    CODE2CC[code] = b.cc;
    const city = liveCluster(b.name)==="C2" ? "Andhra" : "Hyderabad";
    rows.push([code, b.name, city, liveCluster(b.name)]);
    if(liveCluster(b.name)==="C2") c2.push(code); else c1.push(code);
  });
  // overwrite the masters the whole app reads
  BRANCHES.length = 0; rows.forEach(r=>BRANCHES.push(r));
  BR.length = 0; rows.forEach(r=>BR.push(r[0]));
  CFG.c1.br = c1;
  CFG.c2.br = c2;
  CFG.active = BR.slice();
}

/* JS Date from "YYYY-MM-DD" (avoids TZ drift) */
function liveDate(s){
  if(!s) return new Date(TODAY);
  const p = String(s).slice(0,10).split("-");
  return new Date(+p[0], (+p[1])-1, +p[2]);
}

/* map one live invoice -> synthetic INV row shape */
function liveInvRow(iv){
  const code = CC2CODE[iv.cc] || "BR";
  const paid = +iv.paid || 0, tot = +iv.tot || 0;
  const st = tot - paid <= 0.5 ? "Fully Paid" : paid > 0 ? "Part Paid" : "Unpaid";
  return {
    no: iv.no, d: liveDate(iv.d), cli: iv.cli, br: code,
    cat: iv.cat, tr: iv.tr,
    sess: +iv.sess||0, used: +iv.used||0,
    gross: +iv.gross||0, dsc: +iv.dsc||0, dscp: +iv.dscp||0,
    net: +iv.net||0, gst: +iv.gst||0, tot: tot, paid: paid, due: +iv.due||0,
    pm: "—", emp: iv.emp || "—",
    incemp: iv.incemp || "",
    refname: iv.refname || "",
    empsplit: (iv.empsplit && iv.empsplit.length) ? iv.empsplit
              : (iv.emp ? [{name: iv.emp, frac: 1}] : []),
    media: iv.media || "",
    booker: iv.booker || "",
    teller: iv.teller || "",
    gender: iv.gender || "",
    bt: "Direct Walk-In",
    appr: (+iv.dscp||0) >= 30 ? "COO — KBP" : (+iv.dscp||0) >= 20 ? "Cluster Head" : "Centre Manager",
    st: st,
    _cname: iv.cname || ""
  };
}

/* map one live client rollup -> synthetic CLI row shape (light) */
function liveCliRow(c){
  const code = CC2CODE[c.cc] || "BR";
  const cats = (c.cats && c.cats.length) ? c.cats : ["SLIMMING"];
  return {
    id: c.id, uhid: c.id, n: c.n, g: "—", age: 0, ag: "—",
    ph: "—", alt: "—", br: code, city: bCity(code),
    reg: new Date(TODAY), src: (c.src || "Walk-In"), camp: "—",
    cats: cats, cat: cats[0],
    med: "None", alle: "None",
    cons: "—", exec: "—",
    st: "Active", vis: 0, lastV: null, nextA: null,
    bill: +c.bill||0, paid: +c.paid||0, due: +c.due||0,
    invCount: +c.invCount||0, sold: +c.sold||0
  };
}

/* map one live employee -> synthetic EMP row shape (light) */
function liveEmpRow(e){
  // employee.branch is a short name ("Vijayawada") -> find its code
  let code = "—";
  for(const cc in CC2CODE){
    const short = cc.replace(" - LSACPL","").toLowerCase().replace(/\s+/g,"");
    if(short === (e.br||"").toLowerCase().replace(/\s+/g,"")){ code = CC2CODE[cc]; break; }
  }
  return {
    id: e.id, n: e.n, g: e.g||"—", dob: new Date(1990,0,1),
    br: code, dept: e.dept||"—", dg: e.dg||"—",
    ph: "—", em: "—", join: liveDate(e.join),
    prevOrg: "—", prevYr: 0, st: "Active",
    exit: null, rep: "—"
  };
}

/* fetch + hydrate */
async function liveFetch(from, to){
  const url = LIVE.api + "?from_date=" + from + "&to_date=" + to;
  const r = await fetch(url, {headers:{"X-Frappe-CSRF-Token": (window.frappe && frappe.csrf_token) || "", "Accept":"application/json"}, credentials:"same-origin"});
  const j = await r.json();
  const m = j.message || {};
  LIVE.raw = m; LIVE.from = m.from_date; LIVE.to = m.to_date;

  // 1) rebuild branch masters BEFORE mapping (codes come from here)
  liveBuildBranches(m.branches || []);

  // 2) mutate INV in place
  INV.length = 0;
  (m.invoices||[]).forEach(iv=>INV.push(liveInvRow(iv)));
  INV.sort((a,b)=>a.d-b.d);

  // 3) mutate CLI in place  (+ index by id for cliBy)
  CLI.length = 0;
  (m.clients||[]).forEach(c=>CLI.push(liveCliRow(c)));

  // 4) attach live invoice names to each client so cName / drilldown work
  const byId = {};
  CLI.forEach(c=>byId[c.id]=c);
  INV.forEach(iv=>{ const c=byId[iv.cli]; if(c){ if(!c.n && iv._cname) c.n=iv._cname; if((!c.g||c.g==="—") && iv.gender) c.g=iv.gender; } });

  // 5) mutate EMP in place
  EMP.length = 0;
  (m.employees||[]).forEach(e=>EMP.push(liveEmpRow(e)));

  // 6) park session-dependent arrays (agreed): empty so clinical
  //    reports show "clinical feed pending" instead of fake data.
  SESS.length = 0; APPT.length = 0; LEADS.length = 0;

  // 7) collections map: code|YYYY-MM -> {raw, after_gst, net_cuts}
  LIVE_COLL = {};
  (m.collections||[]).forEach(c=>{
    const code = CC2CODE[c.cc];
    if(!code) return;
    // normalise mkey "2026-8" -> "2026-08"
    const p = String(c.mkey||"").split("-");
    const mk = p[0] + "-" + String(p[1]||"").padStart(2,"0");
    const key = code + "|" + mk;
    if(!LIVE_COLL[key]) LIVE_COLL[key] = {raw:0, after_gst:0, net_cuts:0};
    LIVE_COLL[key].raw += (+c.raw||0);
    LIVE_COLL[key].after_gst += (+c.after_gst||0);
    LIVE_COLL[key].net_cuts += (+c.net_cuts||0);
  });

  // 8) targets map: code|YYYY-MM -> target amount
  //    period from_date 2026-08-06 -> business month key 2026-08
  LIVE_TGT = {};
  LIVE_ACH = {};
  (m.targets||[]).forEach(t=>{
    // branch here is the short name ("Banjara Hills") -> code
    let code = "—";
    for(const cc in CC2CODE){
      const short = cc.replace(" - LSACPL","").toLowerCase().replace(/\s+/g,"");
      if(short === (t.branch||"").toLowerCase().replace(/\s+/g,"")){ code = CC2CODE[cc]; break; }
    }
    if(code === "—") return;
    const fp = String(t.from||"").split("-");
    const mk = fp[0] + "-" + String(fp[1]||"").padStart(2,"0");
    const key = code + "|" + mk;
    LIVE_TGT[key] = (+t.target||0);
    LIVE_ACH[key] = (+t.achieved||0);
  });

  // 9) payments -> PAY_BY_INV + dominant payment mode per invoice
  liveApplyPayments(m.payments);

  LIVE.loaded = true;
}

/* payments per invoice, and dominant payment mode set on each INV row.
   Called at the end of liveFetch (after INV is populated). */
function liveApplyPayments(payArr){
  PAY_BY_INV = {};
  (payArr||[]).forEach(p=>{
    const no = p.no;
    if(!PAY_BY_INV[no]) PAY_BY_INV[no] = [];
    PAY_BY_INV[no].push({pe:p.pe, mode:p.mode||"—", d:p.d, amt:+p.amt||0});
  });
  // set dominant mode (by amount) on each invoice
  INV.forEach(iv=>{
    const list = PAY_BY_INV[iv.no];
    if(list && list.length){
      const byMode = {};
      list.forEach(x=>{ byMode[x.mode] = (byMode[x.mode]||0) + x.amt; });
      let best = "—", bestv = -1;
      for(const m in byMode){ if(byMode[m] > bestv){ bestv = byMode[m]; best = m; } }
      iv.pm = best;
    }
  });
}

/* collected for a branch+monthkey (default: after 5% GST cut).
   mode: 'raw' | 'gst' | 'net'  */
function liveColl(code, mk, mode){
  const r = LIVE_COLL[code + "|" + mk];
  if(!r) return 0;
  if(mode === "raw") return r.raw;
  if(mode === "net") return r.net_cuts;
  return r.after_gst;
}
/* total collected across scope for a monthkey */
function liveCollScope(mk, mode){
  let s = 0;
  scopeBR().forEach(b=>{ s += liveColl(b, mk, mode); });
  return s;
}
/* live target for branch+monthkey, 0 if none */
function liveTgt(code, mk){
  return LIVE_TGT[code + "|" + mk] || 0;
}

/* counsellor revenue rows for Report 10, honouring the 50/50 split.
   Each invoice contributes to one or two counsellors per empsplit fracs. */
function liveCounsellorRows(bl){
  const agg = {};   // name -> accumulator
  bl.forEach(iv=>{
    const parts = (iv.empsplit && iv.empsplit.length) ? iv.empsplit
                 : [{name: iv.emp || "—", frac: 1}];
    parts.forEach(p=>{
      const nm = p.name || "—";
      const f = p.frac || 1;
      if(!agg[nm]) agg[nm] = {inv:0, cli:{}, gross:0, dsc:0, tot:0, paid:0, due:0};
      const a = agg[nm];
      a.inv += f;
      a.cli[iv.cli] = 1;
      a.gross += iv.gross * f;
      a.dsc  += iv.dsc  * f;
      a.tot  += iv.tot  * f;
      a.paid += iv.paid * f;
      a.due  += iv.due  * f;
    });
  });
  const rows = Object.keys(agg).map(nm=>{
    const a = agg[nm];
    // resolve to an employee record by name (live emp has .n)
    const e = EMP.find(x=>x.n===nm) || {n:nm, dg:"—", join:new Date(TODAY), prevYr:0, id:nm};
    const g = a.tot;
    return {a:D(e.n, e.dg), _sa:e.n,
      b:Math.round(a.inv), b2:Object.keys(a.cli).length,
      c:a.gross, c2:a.dsc, d:g,
      e:a.paid, e2:a.due,
      f:0, f2:0, g:0, g2:0,                       /* booking route: no live source */
      h:a.inv?Math.round(g/a.inv):0,
      i:+pct(a.paid, g||1),
      j:D(ageStr(e.join), (e.prevYr||0)+" yr prior"),
      _k:e.id};
  });
  return rows.sort((x,y)=>y.d-x.d);
}

/* default window: current month */
function liveDefaultRange(){
  const t = new Date(TODAY);
  const f = new Date(t.getFullYear(), t.getMonth(), 1);
  return [iso(f), iso(t)];
}

