async function liveBoot(){
  BOOTING=true;
  try{
    var fy = new Date(TODAY.getMonth()<3?TODAY.getFullYear()-1:TODAY.getFullYear(),3,1);
    await liveFetch(iso(fy), iso(TODAY));
  }catch(err){
    void 0;
    var m=document.getElementById("main");
    if(m)m.innerHTML='<div class="note" style="margin:24px">Could not load live data from report_master_api. '
      +'Check that the Server Script is enabled and you are logged in.<br><br>'
      +(err&&err.message?("<b>"+err.message+"</b>"):"")+'</div>';
  }
  buildMenu();buildFilters();paintUser();pick(1);
  BOOTING=false;buildMenu();
}
